#!/usr/bin/env python3
import sys, os, re, json, pathlib

VERSION = "deadnix 1.3.1"

class Token:
    __slots__ = ('type','text','line','col','end_line','end_col','offset','end_offset')
    def __init__(self, type_, text, line, col, end_line, end_col, offset, end_offset):
        self.type=type_
        self.text=text
        self.line=line
        self.col=col
        self.end_line=end_line
        self.end_col=end_col
        self.offset=offset
        self.end_offset=end_offset
    def __repr__(self):
        return f"Token({self.type},{self.text!r},{self.line}:{self.col})"

KEYWORDS = {
    'let':'LET',
    'in':'IN',
    'inherit':'INHERIT',
    'rec':'REC',
    'with':'WITH',
    'if':'IF',
    'then':'THEN',
    'else':'ELSE',
    'assert':'ASSERT',
    'or':'OR_KW',
}

def lex(source):
    tokens=[]
    i=0
    line=1
    col=1
    offset=0
    n=len(source)
    lines = source.splitlines()
    skip_lines = set()
    for idx, l in enumerate(lines, start=1):
        if 'deadnix: skip' in l:
            skip_lines.add(idx)

    state_stack = [{'type':'CODE'}]

    def add_token(type_, text, sl, sc, el, ec, soff, eoff):
        tokens.append(Token(type_, text, sl, sc, el, ec, soff, eoff))

    while i < n:
        cur = state_stack[-1]
        if cur['type']=='CODE':
            c=source[i]
            if c in ' \t\r':
                j=i
                while j<n and source[j] in ' \t\r':
                    j+=1
                for _ in range(j-i):
                    col+=1
                    offset+=1
                i=j
                continue
            if c=='\n':
                line+=1
                col=1
                offset+=1
                i+=1
                continue
            if c=='#':
                sl=line; sc=col; soff=offset
                j=i
                while j<n and source[j]!='\n':
                    j+=1
                text=source[i:j]
                add_token('COMMENT', text, sl, sc, line, col+len(text), soff, offset+len(text))
                for _ in text:
                    col+=1
                    offset+=1
                i=j
                continue
            if source[i:i+2]=='/*':
                sl=line; sc=col; soff=offset
                j=i+2
                # scan to */
                k=j
                tmp_line=line
                tmp_col=col+2
                while k<n:
                    if source[k:k+2]=='*/':
                        k+=2
                        break
                    if source[k]=='\n':
                        tmp_line+=1
                        tmp_col=1
                    else:
                        tmp_col+=1
                    k+=1
                text=source[i:k]
                # compute end line/col
                nl=text.count('\n')
                if nl==0:
                    el=sl; ec=sc+len(text)
                else:
                    el=sl+nl
                    last_nl=text.rfind('\n')
                    ec=len(text)-last_nl
                add_token('COMMENT_BLOCK', text, sl, sc, el, ec, soff, soff+len(text))
                for ch in text:
                    if ch=='\n':
                        line+=1
                        col=1
                    else:
                        col+=1
                    offset+=1
                i=k
                continue
            if c=='"':
                sl=line; sc=col; soff=offset
                state_stack.append({'type':'STRING_DQ','start_line':sl,'start_col':sc,'start_offset':soff})
                col+=1; offset+=1; i+=1
                continue
            if source[i:i+2]=="''":
                sl=line; sc=col; soff=offset
                state_stack.append({'type':'IND_STRING','start_line':sl,'start_col':sc,'start_offset':soff})
                col+=2; offset+=2; i+=2
                continue
            if source[i:i+3]=='...':
                sl=line; sc=col; soff=offset
                add_token('ELLIPSIS','...',sl,sc,line,col+3,soff,offset+3)
                col+=3; offset+=3; i+=3
                continue
            if c.isalpha() or c=='_':
                sl=line; sc=col; soff=offset
                j=i
                while j<n and (source[j].isalnum() or source[j] in "_-'"):
                    j+=1
                text=source[i:j]
                ttype=KEYWORDS.get(text,'IDENT')
                add_token(ttype,text,sl,sc,line,col+len(text),soff,offset+len(text))
                for _ in text:
                    col+=1; offset+=1
                i=j
                continue
            if c.isdigit():
                sl=line; sc=col; soff=offset
                j=i
                while j<n and (source[j].isdigit() or source[j]=='.'):
                    j+=1
                text=source[i:j]
                add_token('NUMBER',text,sl,sc,line,col+len(text),soff,offset+len(text))
                for _ in text:
                    col+=1; offset+=1
                i=j
                continue
            sym_map = {
                '{':'L_BRACE',
                '}':'R_BRACE',
                '[':'L_BRACK',
                ']':'R_BRACK',
                '(':'L_PAREN',
                ')':'R_PAREN',
                '=':'EQ',
                ';':'SEMI',
                ':':'COLON',
                ',':'COMMA',
                '.':'DOT',
                '@':'AT',
                '?':'QUESTION',
            }
            if c in sym_map:
                sl=line; sc=col; soff=offset
                if c=='}' and cur.get('is_interp'):
                    if cur.get('brace_depth',0)>0:
                        cur['brace_depth']-=1
                        add_token('R_BRACE',c,sl,sc,line,col+1,soff,offset+1)
                        col+=1; offset+=1; i+=1
                        continue
                    else:
                        add_token('INTERP_END',c,sl,sc,line,col+1,soff,offset+1)
                        col+=1; offset+=1; i+=1
                        state_stack.pop()
                        continue
                if c=='{' and cur.get('is_interp'):
                    cur['brace_depth']=cur.get('brace_depth',0)+1
                add_token(sym_map[c],c,sl,sc,line,col+1,soff,offset+1)
                col+=1; offset+=1; i+=1
                continue
            if c in '+-*/<>!&|':
                sl=line; sc=col; soff=offset
                j=i
                while j<n and source[j] in '+-*/<>!=&|':
                    j+=1
                text=source[i:j]
                add_token('OP',text,sl,sc,line,col+len(text),soff,offset+len(text))
                for _ in text:
                    col+=1; offset+=1
                i=j
                continue
            if c=='$':
                sl=line; sc=col; soff=offset
                add_token('DOLLAR',c,sl,sc,line,col+1,soff,offset+1)
                col+=1; offset+=1; i+=1
                continue
            col+=1; offset+=1; i+=1
            continue
        elif cur['type']=='STRING_DQ':
            if i>=n:
                sl=cur['start_line']; sc=cur['start_col']; soff=cur['start_offset']
                text=source[soff:i]
                add_token('STRING',text,sl,sc,line,col,soff,offset)
                state_stack.pop()
                break
            if source[i]=='\\':
                if i+1<n:
                    if source[i+1]=='\n':
                        line+=1; col=1
                    else:
                        col+=2
                    offset+=2; i+=2
                else:
                    col+=1; offset+=1; i+=1
                continue
            if source[i:i+2]=='${':
                sl=line; sc=col; soff=offset
                add_token('INTERP_START','${',sl,sc,line,col+2,soff,offset+2)
                col+=2; offset+=2; i+=2
                state_stack.append({'type':'CODE','is_interp':True,'brace_depth':0})
                continue
            if source[i]=='"':
                sl=cur['start_line']; sc=cur['start_col']; soff=cur['start_offset']
                text=source[soff:i+1]
                el=line; ec=col+1
                add_token('STRING',text,sl,sc,el,ec,soff,offset+1)
                col+=1; offset+=1; i+=1
                state_stack.pop()
                continue
            if source[i]=='\n':
                line+=1; col=1; offset+=1; i+=1
            else:
                col+=1; offset+=1; i+=1
            continue
        elif cur['type']=='IND_STRING':
            if i+1<n and source[i:i+2]=="''":
                # check if escaped: ''' or ''${ ?
                if source[i:i+3]=="'''":
                    col+=3; offset+=3; i+=3
                    continue
                if i+2<n and source[i+2]=='$' and i+3<n and source[i+3]=='{':
                    # ''${ is escaped interpolation, not start
                    col+=2; offset+=2; i+=2
                    continue
                sl=cur['start_line']; sc=cur['start_col']; soff=cur['start_offset']
                text=source[soff:i+2]
                # compute end line/col
                nl=text.count('\n')
                if nl==0:
                    el=sl; ec=sc+len(text)
                else:
                    el=sl+nl
                    last=text.rfind('\n')
                    ec=len(text)-last
                add_token('STRING',text,sl,sc,el,ec,soff,soff+len(text))
                for ch in text[2:]: # we already counted start ''? Actually we need to advance correctly
                    pass
                # advance by len of remaining? We already handled start, we need to advance for the '' end
                # Instead of recomputing, just advance line/col by scanning text from current position? Simpler: advance by 2 and handle newlines already counted? We'll just advance for the ''
                # We have line/col currently at start of '', need to advance 2
                # But we also need to account for any newlines inside the string that we didn't track? We tracked line/col while inside IND_STRING via per-char handling, so line/col already at this point is correct start of ''.
                col+=2; offset+=2; i+=2
                state_stack.pop()
                continue
            if source[i:i+2]=='${':
                sl=line; sc=col; soff=offset
                add_token('INTERP_START','${',sl,sc,line,col+2,soff,offset+2)
                col+=2; offset+=2; i+=2
                state_stack.append({'type':'CODE','is_interp':True,'brace_depth':0})
                continue
            if source[i]=='\n':
                line+=1; col=1; offset+=1; i+=1
            else:
                col+=1; offset+=1; i+=1
            continue
    return tokens, skip_lines, lines

class Parser:
    def __init__(self, tokens, source, lines, skip_lines):
        self.tokens=tokens
        self.pos=0
        self.source=source
        self.lines=lines
        self.skip_lines=skip_lines

    def peek(self, off=0):
        idx=self.pos+off
        if idx < len(self.tokens):
            return self.tokens[idx]
        return None

    def consume(self, typ=None):
        t=self.peek()
        if t is None:
            return None
        if typ and t.type!=typ:
            return None
        self.pos+=1
        return t

    def expect(self, typ):
        return self.consume(typ)

    def skip_comments(self):
        while True:
            t=self.peek()
            if t and t.type in ('COMMENT','COMMENT_BLOCK'):
                self.pos+=1
            else:
                break

    def parse(self):
        self.skip_comments()
        if self.pos>=len(self.tokens):
            return None
        return self.parse_expr()

    def parse_expr(self):
        self.skip_comments()
        t=self.peek()
        if t is None:
            return None
        if t.type=='LET':
            return self.parse_let()
        if t.type=='WITH':
            return self.parse_with()
        # try lambda
        saved=self.pos
        param=self.try_parse_lambda_param()
        if param is not None:
            self.skip_comments()
            nxt=self.peek()
            if nxt and nxt.type=='COLON':
                self.consume('COLON')
                body=self.parse_expr()
                return {'type':'lambda','param':param,'body':body}
            self.pos=saved
        # fallback term + application
        expr=self.parse_term()
        if expr is None:
            return None
        args=[]
        while True:
            self.skip_comments()
            nxt=self.peek()
            if nxt is None:
                break
            if nxt.type in ('IN','SEMI','R_BRACE','R_BRACK','R_PAREN','COMMA','ELSE','THEN'):
                break
            if nxt.type in ('IDENT','L_BRACE','L_BRACK','L_PAREN','STRING','NUMBER','REC','IF','ASSERT','INTERP_START'):
                term=self.parse_term()
                if term:
                    args.append(term)
                else:
                    break
            else:
                break
        if args:
            return {'type':'app','func':expr,'args':args}
        return expr

    def parse_term(self):
        self.skip_comments()
        t=self.peek()
        if t is None:
            return None
        if t.type=='L_BRACE':
            return self.parse_attrset()
        if t.type=='L_BRACK':
            return self.parse_list()
        if t.type=='L_PAREN':
            self.consume('L_PAREN')
            inner=self.parse_expr()
            self.skip_comments()
            self.consume('R_PAREN')
            return inner
        if t.type=='IDENT':
            ident=self.consume('IDENT')
            path=[ident.text]
            # handle attr path like a.b.c
            while True:
                self.skip_comments()
                nxt=self.peek()
                if nxt and nxt.type=='DOT':
                    self.consume('DOT')
                    nn=self.peek()
                    if nn and nn.type=='IDENT':
                        self.consume('IDENT')
                        path.append(nn.text)
                    elif nn and nn.type=='STRING':
                        self.consume('STRING')
                        path.append('<string>')
                    else:
                        break
                else:
                    break
            return {'type':'var','name':ident.text,'line':ident.line,'col':ident.col,'end_col':ident.end_col,'path':path,'tok':ident}
        if t.type=='INTERP_START':
            self.consume('INTERP_START')
            expr=self.parse_expr()
            self.skip_comments()
            self.consume('INTERP_END')
            return expr
        if t.type=='STRING':
            # string with possible preceding interpolations that are already parsed? For our token stream, interpolation tokens appear before STRING ends.
            # But in parse_term, if we are at STRING, we need to handle that there may be preceding interpolation tokens that were already consumed as part of previous parse? Actually our parse_expr for term sequence would treat interpolation as separate term, not as part of string. So we need to collect string and interpolations as one.
            # We'll collect consecutive STRING and INTERP_START blocks.
            return self.parse_string_with_interps()
        if t.type=='NUMBER':
            self.consume('NUMBER')
            return {'type':'literal'}
        if t.type=='REC':
            self.consume('REC')
            self.skip_comments()
            if self.peek() and self.peek().type=='L_BRACE':
                return self.parse_attrset(rec=True)
            return {'type':'rec'}
        if t.type=='IF':
            self.consume('IF')
            cond=self.parse_expr()
            self.skip_comments()
            self.consume('THEN')
            then_e=self.parse_expr()
            self.skip_comments()
            self.consume('ELSE')
            else_e=self.parse_expr()
            return {'type':'if','cond':cond,'then':then_e,'else':else_e}
        if t.type=='ASSERT':
            self.consume('ASSERT')
            cond=self.parse_expr()
            self.skip_comments()
            self.consume('SEMI')
            body=self.parse_expr()
            return {'type':'assert','cond':cond,'body':body}
        # unknown, skip
        self.pos+=1
        return None

    def parse_string_with_interps(self):
        exprs=[]
        while True:
            self.skip_comments()
            t=self.peek()
            if t is None:
                break
            if t.type=='STRING':
                self.consume('STRING')
                continue
            if t.type=='INTERP_START':
                self.consume('INTERP_START')
                e=self.parse_expr()
                if e:
                    exprs.append(e)
                self.skip_comments()
                self.consume('INTERP_END')
                continue
            break
        if exprs:
            return {'type':'string_interp','exprs':exprs}
        return {'type':'string'}

    def parse_attrset(self, rec=False):
        self.skip_comments()
        start=self.consume('L_BRACE')
        if start is None:
            return None
        bindings=[]
        while True:
            self.skip_comments()
            t=self.peek()
            if t is None:
                break
            if t.type=='R_BRACE':
                self.consume('R_BRACE')
                break
            if t.type=='INHERIT':
                inh=self.parse_inherit()
                if inh:
                    bindings.append(inh)
                continue
            # attr assignment: attrpath = expr ;
            attrpath=self.parse_attrpath()
            if attrpath is None:
                # skip token
                self.pos+=1
                continue
            self.skip_comments()
            eq=self.consume('EQ')
            if eq is None:
                # skip to semi or rbrace
                while self.peek() and self.peek().type not in ('SEMI','R_BRACE'):
                    self.pos+=1
                if self.peek() and self.peek().type=='SEMI':
                    self.consume('SEMI')
                continue
            self.skip_comments()
            expr=self.parse_expr()
            self.skip_comments()
            self.consume('SEMI')
            # attrpath is list of (name, tok) maybe
            # For our usage, we just keep first identifier as potential? Attrset bindings not checked for dead, but need keys for with.
            bindings.append({'type':'attr_assign','path':attrpath,'expr':expr})
        return {'type':'attrset','rec':rec,'bindings':bindings,'line':start.line if start else 0}

    def parse_attrpath(self):
        self.skip_comments()
        path=[]
        toks=[]
        while True:
            self.skip_comments()
            t=self.peek()
            if t is None:
                break
            if t.type=='IDENT':
                tok=self.consume('IDENT')
                path.append(tok.text)
                toks.append(tok)
            elif t.type=='STRING':
                self.consume('STRING')
                path.append('<string>')
                toks.append(t)
            elif t.type=='INTERP_START':
                self.consume('INTERP_START')
                e=self.parse_expr()
                self.consume('INTERP_END')
                path.append('<interp>')
                # e contains var refs that should be counted as usage in attrpath? For attrset key like "${a}" = 1, the a is usage in outer scope? Earlier test: let a=1; in { "${a}" = 2; } => no unused? Actually earlier we tested let a=1; in { "${a}" = 1; } => no unused? We observed "let a=1; in { \"${a}\" = 1; }" => empty (no unused) so a used via interpolated key.
                # So we need to capture interpolation exprs in attrpath for usage.
                # We'll store exprs in a side list attached to path object? We can store in toks as well.
                # For simplicity, we will attach inner exprs to a global? Instead, we can return a structure that includes exprs.
                # We'll store e in path as special.
                # Let's store tuple.
                # We'll create a dict for attrpath node that includes name and exprs.
                # Simplify: we will return list of path components and also list of exprs found in interpolations.
                # We'll need to handle.
                # For now, we will just ignore but we need to collect usages.
                # We'll add to a list on parser object?
                # Let's create a temporary attribute to hold last interpolation exprs
                if not hasattr(self,'_attrpath_interps'):
                    self._attrpath_interps=[]
                self._attrpath_interps.append(e)
            else:
                break
            self.skip_comments()
            nxt=self.peek()
            if nxt and nxt.type=='DOT':
                self.consume('DOT')
                continue
            break
        if path:
            # If we have interpolation exprs collected, we need to return them as well
            interps=getattr(self,'_attrpath_interps',[])
            # reset
            self._attrpath_interps=[]
            return {'names':path,'toks':toks,'interps':interps}
        return None

    def parse_inherit(self):
        self.skip_comments()
        inherit_tok=self.consume('INHERIT')
        if inherit_tok is None:
            return None
        self.skip_comments()
        from_expr=None
        if self.peek() and self.peek().type=='L_PAREN':
            self.consume('L_PAREN')
            from_expr=self.parse_expr()
            self.skip_comments()
            self.consume('R_PAREN')
        idents=[]
        while True:
            self.skip_comments()
            tok=self.peek()
            if tok and tok.type=='IDENT':
                id_tok=self.consume('IDENT')
                is_skipped = (id_tok.line-1) in self.skip_lines
                idents.append({'name':id_tok.text,'line':id_tok.line,'col':id_tok.col,'end_col':id_tok.end_col,'skip':is_skipped,'tok':id_tok})
            else:
                break
        self.skip_comments()
        self.consume('SEMI')
        return {'type':'inherit','from':from_expr,'idents':idents,'line':inherit_tok.line}

    def parse_let(self):
        let_tok=self.consume('LET')
        bindings=[]
        while True:
            self.skip_comments()
            tok=self.peek()
            if tok is None:
                break
            if tok.type=='IN':
                self.consume('IN')
                break
            if tok.type=='INHERIT':
                inh=self.parse_inherit()
                if inh:
                    bindings.append(inh)
                continue
            # binding: attrpath = expr ;
            # need to lookahead to ensure next is IDENT (start of attrpath)
            # For simplicity, check if peek is IDENT
            if tok.type!='IDENT' and tok.type!='STRING':
                # maybe unexpected, skip
                self.pos+=1
                continue
            # parse attrpath
            attrpath=self.parse_attrpath()
            if attrpath is None:
                self.pos+=1
                continue
            self.skip_comments()
            eq=self.consume('EQ')
            if eq is None:
                # skip to semi
                while self.peek() and self.peek().type not in ('SEMI','IN'):
                    self.pos+=1
                if self.peek() and self.peek().type=='SEMI':
                    self.consume('SEMI')
                continue
            self.skip_comments()
            expr=self.parse_expr()
            self.skip_comments()
            self.consume('SEMI')
            # First name is binding name
            first_name = attrpath['names'][0] if attrpath['names'] else None
            first_tok = attrpath['toks'][0] if attrpath['toks'] else None
            if first_name and first_name not in ('<string>','<interp>'):
                line=first_tok.line if first_tok else 0
                col=first_tok.col if first_tok else 0
                end_col=first_tok.end_col if first_tok else 0
                is_skipped = (line-1) in self.skip_lines
                bindings.append({'type':'binding','name':first_name,'expr':expr,'line':line,'col':col,'end_col':end_col,'skip':is_skipped,'attrpath':attrpath,'tok':first_tok})
        body=self.parse_expr()
        return {'type':'let','bindings':bindings,'body':body,'line':let_tok.line if let_tok else 0}

    def parse_with(self):
        with_tok=self.consume('WITH')
        expr=self.parse_expr()
        self.skip_comments()
        self.consume('SEMI')
        body=self.parse_expr()
        return {'type':'with','expr':expr,'body':body,'line':with_tok.line if with_tok else 0}

    def try_parse_lambda_param(self):
        saved=self.pos
        self.skip_comments()
        tok=self.peek()
        if tok is None:
            return None
        if tok.type=='IDENT':
            ident_tok=self.consume('IDENT')
            self.skip_comments()
            nxt=self.peek()
            if nxt and nxt.type=='AT':
                self.consume('AT')
                self.skip_comments()
                nxt2=self.peek()
                if nxt2 and nxt2.type=='L_BRACE':
                    pat=self.parse_pattern()
                    if pat:
                        return {'type':'at_pattern','at_name':{'name':ident_tok.text,'line':ident_tok.line,'col':ident_tok.col,'end_col':ident_tok.end_col,'skip': (ident_tok.line-1) in self.skip_lines},'pattern':pat}
                elif nxt2 and nxt2.type=='IDENT':
                    ident2=self.consume('IDENT')
                    pat={'type':'simple','name':ident2.text,'line':ident2.line,'col':ident2.col,'end_col':ident2.end_col,'skip': (ident2.line-1) in self.skip_lines}
                    return {'type':'at_pattern','at_name':{'name':ident_tok.text,'line':ident_tok.line,'col':ident_tok.col,'end_col':ident_tok.end_col,'skip': (ident_tok.line-1) in self.skip_lines},'pattern':pat}
                else:
                    self.pos=saved
                    return None
            else:
                return {'type':'simple','name':ident_tok.text,'line':ident_tok.line,'col':ident_tok.col,'end_col':ident_tok.end_col,'skip': (ident_tok.line-1) in self.skip_lines}
        if tok.type=='L_BRACE':
            pat=self.parse_pattern()
            if pat is None:
                self.pos=saved
                return None
            self.skip_comments()
            nxt=self.peek()
            if nxt and nxt.type=='AT':
                self.consume('AT')
                self.skip_comments()
                ident_tok=self.consume('IDENT')
                if ident_tok is None:
                    self.pos=saved
                    return None
                return {'type':'at_pattern','pattern':pat,'at_name':{'name':ident_tok.text,'line':ident_tok.line,'col':ident_tok.col,'end_col':ident_tok.end_col,'skip': (ident_tok.line-1) in self.skip_lines}}
            else:
                return pat
        return None

    def parse_pattern(self):
        self.skip_comments()
        l_brace=self.consume('L_BRACE')
        if l_brace is None:
            return None
        entries=[]
        has_ellipsis=False
        while True:
            self.skip_comments()
            tok=self.peek()
            if tok is None:
                break
            if tok.type=='R_BRACE':
                self.consume('R_BRACE')
                break
            if tok.type=='ELLIPSIS':
                has_ellipsis=True
                self.consume('ELLIPSIS')
                self.skip_comments()
                if self.peek() and self.peek().type=='COMMA':
                    self.consume('COMMA')
                continue
            if tok.type=='IDENT':
                ident_tok=self.consume('IDENT')
                self.skip_comments()
                default_expr=None
                if self.peek() and self.peek().type=='QUESTION':
                    self.consume('QUESTION')
                    self.skip_comments()
                    default_expr=self.parse_expr()
                self.skip_comments()
                if self.peek() and self.peek().type=='COMMA':
                    self.consume('COMMA')
                is_skipped = (ident_tok.line-1) in self.skip_lines
                entries.append({'name':ident_tok.text,'line':ident_tok.line,'col':ident_tok.col,'end_col':ident_tok.end_col,'default':default_expr,'skip':is_skipped,'tok':ident_tok})
                continue
            if tok.type=='COMMA':
                self.consume('COMMA')
                continue
            # unexpected
            self.pos+=1
        return {'type':'pattern','entries':entries,'ellipsis':has_ellipsis,'line':l_brace.line}

    def parse_list(self):
        self.consume('L_BRACK')
        elems=[]
        while True:
            self.skip_comments()
            tok=self.peek()
            if tok is None or tok.type=='R_BRACK':
                self.consume('R_BRACK')
                break
            expr=self.parse_expr()
            if expr:
                elems.append(expr)
        return {'type':'list','elems':elems}

def collect_refs(node):
    if node is None:
        return set()
    t=node.get('type')
    if t=='var':
        return {node['name']}
    if t=='let':
        s=set()
        for b in node['bindings']:
            if b['type']=='binding':
                if b['expr']:
                    s.update(collect_refs(b['expr']))
            elif b['type']=='inherit':
                if b['from']:
                    s.update(collect_refs(b['from']))
        s.update(collect_refs(node['body']))
        return s
    if t=='with':
        s=set()
        s.update(collect_refs(node['expr']))
        s.update(collect_refs(node['body']))
        return s
    if t=='lambda':
        s=set()
        param=node['param']
        if param['type']=='pattern':
            for e in param['entries']:
                if e['default']:
                    s.update(collect_refs(e['default']))
        elif param['type']=='at_pattern':
            pat=param.get('pattern')
            if pat:
                if pat['type']=='pattern':
                    for en in pat['entries']:
                        if en['default']:
                            s.update(collect_refs(en['default']))
        s.update(collect_refs(node['body']))
        return s
    if t=='attrset':
        s=set()
        for b in node['bindings']:
            if b['type']=='inherit':
                if b['from']:
                    s.update(collect_refs(b['from']))
                if b['from'] is None:
                    for ident in b['idents']:
                        s.add(ident['name'])
            elif b['type']=='attr_assign':
                if b['expr']:
                    s.update(collect_refs(b['expr']))
                # also need interps in attrpath?
                # attrpath interps are stored in b['path']['interps']?
                # our attrpath returns dict with interps
                ap=b.get('path')
                if isinstance(ap, dict) and 'interps' in ap:
                    for inter in ap['interps']:
                        s.update(collect_refs(inter))
        return s
    if t=='list':
        s=set()
        for e in node['elems']:
            s.update(collect_refs(e))
        return s
    if t=='app':
        s=set()
        s.update(collect_refs(node['func']))
        for a in node['args']:
            s.update(collect_refs(a))
        return s
    if t=='string_interp':
        s=set()
        for e in node['exprs']:
            s.update(collect_refs(e))
        return s
    if t=='if':
        s=set()
        s.update(collect_refs(node['cond']))
        s.update(collect_refs(node['then']))
        s.update(collect_refs(node['else']))
        return s
    if t=='assert':
        s=set()
        s.update(collect_refs(node['cond']))
        s.update(collect_refs(node['body']))
        return s
    return set()

