        cur = state_stack[-1]
        if cur['type']=='CODE':
            c=source[i]
            if c in ' \t\r':
                j=i
                while j<n and source[j] in ' \t\r':
                    j+=1
                for _ in range(j-i):
                    col+=1
                    offset+=1
                i=j
                continue
            if c=='\n':
                line+=1
                col=1
                offset+=1
                i+=1
                continue
            if c=='#':
                sl=line; sc=col; soff=offset
                j=i
                while j<n and source[j]!='\n':
                    j+=1
                text=source[i:j]
                add_token('COMMENT', text, sl, sc, line, col+len(text), soff, offset+len(text))
                for _ in text:
                    col+=1
                    offset+=1
                i=j
                continue
            if source[i:i+2]=='/*':
                sl=line; sc=col; soff=offset
                j=i+2
                # scan to */
                k=j
                tmp_line=line
                tmp_col=col+2
                while k<n:
                    if source[k:k+2]=='*/':
                        k+=2
                        break
                    if source[k]=='\n':
                        tmp_line+=1
                        tmp_col=1
                    else:
                        tmp_col+=1
                    k+=1
                text=source[i:k]
                # compute end line/col
                nl=text.count('\n')
                if nl==0:
                    el=sl; ec=sc+len(text)
                else:
                    el=sl+nl
                    last_nl=text.rfind('\n')
                    ec=len(text)-last_nl
                add_token('COMMENT_BLOCK', text, sl, sc, el, ec, soff, soff+len(text))
                for ch in text:
                    if ch=='\n':
                        line+=1
                        col=1
                    else:
                        col+=1
                    offset+=1
                i=k
                continue
            if c=='"':
                sl=line; sc=col; soff=offset
                state_stack.append({'type':'STRING_DQ','start_line':sl,'start_col':sc,'start_offset':soff})
                col+=1; offset+=1; i+=1
                continue
            if source[i:i+2]=="''":
                sl=line; sc=col; soff=offset
                state_stack.append({'type':'IND_STRING','start_line':sl,'start_col':sc,'start_offset':soff})
                col+=2; offset+=2; i+=2
                continue
            if source[i:i+3]=='...':
                sl=line; sc=col; soff=offset
                add_token('ELLIPSIS','...',sl,sc,line,col+3,soff,offset+3)
                col+=3; offset+=3; i+=3
                continue
            if c.isalpha() or c=='_':
                sl=line; sc=col; soff=offset
                j=i
                while j<n and (source[j].isalnum() or source[j] in "_-'"):
