                    col+=1; offset+=1
                i=j
                continue
            if c=='$':
                sl=line; sc=col; soff=offset
                add_token('DOLLAR',c,sl,sc,line,col+1,soff,offset+1)
                col+=1; offset+=1; i+=1
                continue
            col+=1; offset+=1; i+=1
            continue
        elif cur['type']=='STRING_DQ':
            if i>=n:
                sl=cur['start_line']; sc=cur['start_col']; soff=cur['start_offset']
                text=source[soff:i]
                add_token('STRING',text,sl,sc,line,col,soff,offset)
                state_stack.pop()
                break
            if source[i]=='\\':
                if i+1<n:
                    if source[i+1]=='\n':
                        line+=1; col=1
                    else:
                        col+=2
                    offset+=2; i+=2
                else:
                    col+=1; offset+=1; i+=1
                continue
            if source[i:i+2]=='${':
                sl=line; sc=col; soff=offset
                add_token('INTERP_START','${',sl,sc,line,col+2,soff,offset+2)
                col+=2; offset+=2; i+=2
                state_stack.append({'type':'CODE','is_interp':True,'brace_depth':0})
                continue
            if source[i]=='"':
                sl=cur['start_line']; sc=cur['start_col']; soff=cur['start_offset']
                text=source[soff:i+1]
                el=line; ec=col+1
                add_token('STRING',text,sl,sc,el,ec,soff,offset+1)
                col+=1; offset+=1; i+=1
                state_stack.pop()
                continue
            if source[i]=='\n':
                line+=1; col=1; offset+=1; i+=1
            else:
                col+=1; offset+=1; i+=1
            continue
        elif cur['type']=='IND_STRING':
            if i+1<n and source[i:i+2]=="''":
                # check if escaped: ''' or ''${ ?
                if source[i:i+3]=="'''":
                    col+=3; offset+=3; i+=3
                    continue
                if i+2<n and source[i+2]=='$' and i+3<n and source[i+3]=='{':
                    # ''${ is escaped interpolation, not start
                    col+=2; offset+=2; i+=2
                    continue
                sl=cur['start_line']; sc=cur['start_col']; soff=cur['start_offset']
                text=source[soff:i+2]
                # compute end line/col
                nl=text.count('\n')
                if nl==0:
                    el=sl; ec=sc+len(text)
                else:
                    el=sl+nl
                    last=text.rfind('\n')
                    ec=len(text)-last
                add_token('STRING',text,sl,sc,el,ec,soff,soff+len(text))
                for ch in text[2:]: # we already counted start ''? Actually we need to advance correctly
                    pass
                # advance by len of remaining? We already handled start, we need to advance for the '' end
                # Instead of recomputing, just advance line/col by scanning text from current position? Simpler: advance by 2 and handle newlines already counted? We'll just advance for the ''
                # We have line/col currently at start of '', need to advance 2
                # But we also need to account for any newlines inside the string that we didn't track? We tracked line/col while inside IND_STRING via per-char handling, so line/col already at this point is correct start of ''.
                col+=2; offset+=2; i+=2
                state_stack.pop()
                continue
            if source[i:i+2]=='${':
                sl=line; sc=col; soff=offset
                add_token('INTERP_START','${',sl,sc,line,col+2,soff,offset+2)
                col+=2; offset+=2; i+=2
                state_stack.append({'type':'CODE','is_interp':True,'brace_depth':0})
                continue
            if source[i]=='\n':
                line+=1; col=1; offset+=1; i+=1
            else:
                col+=1; offset+=1; i+=1
            continue
