        if t.type=='IF':
            self.consume('IF')
            cond=self.parse_expr()
            self.skip_comments()
            self.consume('THEN')
            then_e=self.parse_expr()
            self.skip_comments()
            self.consume('ELSE')
            else_e=self.parse_expr()
            return {'type':'if','cond':cond,'then':then_e,'else':else_e}
        if t.type=='ASSERT':
