                # We'll add to a list on parser object?
                # Let's create a temporary attribute to hold last interpolation exprs
                if not hasattr(self,'_attrpath_interps'):
                    self._attrpath_interps=[]
                self._attrpath_interps.append(e)
            else:
                break
            self.skip_comments()
            nxt=self.peek()
            if nxt and nxt.type=='DOT':
                self.consume('DOT')
                continue
            break
        if path:
            # If we have interpolation exprs collected, we need to return them as well
            interps=getattr(self,'_attrpath_interps',[])
            # reset
