    def parse_inherit(self):
        self.skip_comments()
        inherit_tok=self.consume('INHERIT')
        if inherit_tok is None:
            return None
        self.skip_comments()
        from_expr=None
        if self.peek() and self.peek().type=='L_PAREN':
            self.consume('L_PAREN')
            from_expr=self.parse_expr()
            self.skip_comments()
            self.consume('R_PAREN')
        idents=[]
        while True:
            self.skip_comments()
            tok=self.peek()
            if tok and tok.type=='IDENT':
                id_tok=self.consume('IDENT')
                is_skipped = (id_tok.line-1) in self.skip_lines
                idents.append({'name':id_tok.text,'line':id_tok.line,'col':id_tok.col,'end_col':id_tok.end_col,'skip':is_skipped,'tok':id_tok})
            else:
                break
        self.skip_comments()
        self.consume('SEMI')
        return {'type':'inherit','from':from_expr,'idents':idents,'line':inherit_tok.line}

    def parse_let(self):
        let_tok=self.consume('LET')
        bindings=[]
        while True:
            self.skip_comments()
            tok=self.peek()
            if tok is None:
                break
            if tok.type=='IN':
                self.consume('IN')
                break
            if tok.type=='INHERIT':
                inh=self.parse_inherit()
                if inh:
                    bindings.append(inh)
                continue
            # binding: attrpath = expr ;
            # need to lookahead to ensure next is IDENT (start of attrpath)
            # For simplicity, check if peek is IDENT
            if tok.type!='IDENT' and tok.type!='STRING':
                # maybe unexpected, skip
                self.pos+=1
                continue
            # parse attrpath
            attrpath=self.parse_attrpath()
            if attrpath is None:
                self.pos+=1
                continue
            self.skip_comments()
            eq=self.consume('EQ')
            if eq is None:
                # skip to semi
                while self.peek() and self.peek().type not in ('SEMI','IN'):
                    self.pos+=1
                if self.peek() and self.peek().type=='SEMI':
                    self.consume('SEMI')
                continue
            self.skip_comments()
            expr=self.parse_expr()
            self.skip_comments()
            self.consume('SEMI')
            # First name is binding name
            first_name = attrpath['names'][0] if attrpath['names'] else None
            first_tok = attrpath['toks'][0] if attrpath['toks'] else None
            if first_name and first_name not in ('<string>','<interp>'):
                line=first_tok.line if first_tok else 0
                col=first_tok.col if first_tok else 0
                end_col=first_tok.end_col if first_tok else 0
                is_skipped = (line-1) in self.skip_lines
                bindings.append({'type':'binding','name':first_name,'expr':expr,'line':line,'col':col,'end_col':end_col,'skip':is_skipped,'attrpath':attrpath,'tok':first_tok})
        body=self.parse_expr()
        return {'type':'let','bindings':bindings,'body':body,'line':let_tok.line if let_tok else 0}

    def parse_with(self):
        with_tok=self.consume('WITH')
        expr=self.parse_expr()
        self.skip_comments()
        self.consume('SEMI')
        body=self.parse_expr()
        return {'type':'with','expr':expr,'body':body,'line':with_tok.line if with_tok else 0}

    def try_parse_lambda_param(self):
        saved=self.pos
        self.skip_comments()
        tok=self.peek()
        if tok is None:
            return None
        if tok.type=='IDENT':
            ident_tok=self.consume('IDENT')
            self.skip_comments()
            nxt=self.peek()
            if nxt and nxt.type=='AT':
                self.consume('AT')
                self.skip_comments()
                nxt2=self.peek()
                if nxt2 and nxt2.type=='L_BRACE':
                    pat=self.parse_pattern()
                    if pat:
                        return {'type':'at_pattern','at_name':{'name':ident_tok.text,'line':ident_tok.line,'col':ident_tok.col,'end_col':ident_tok.end_col,'skip': (ident_tok.line-1) in self.skip_lines},'pattern':pat}
                elif nxt2 and nxt2.type=='IDENT':
                    ident2=self.consume('IDENT')
                    pat={'type':'simple','name':ident2.text,'line':ident2.line,'col':ident2.col,'end_col':ident2.end_col,'skip': (ident2.line-1) in self.skip_lines}
                    return {'type':'at_pattern','at_name':{'name':ident_tok.text,'line':ident_tok.line,'col':ident_tok.col,'end_col':ident_tok.end_col,'skip': (ident_tok.line-1) in self.skip_lines},'pattern':pat}
                else:
                    self.pos=saved
                    return None
            else:
                return {'type':'simple','name':ident_tok.text,'line':ident_tok.line,'col':ident_tok.col,'end_col':ident_tok.end_col,'skip': (ident_tok.line-1) in self.skip_lines}
        if tok.type=='L_BRACE':
            pat=self.parse_pattern()
            if pat is None:
                self.pos=saved
                return None
            self.skip_comments()
            nxt=self.peek()
            if nxt and nxt.type=='AT':
                self.consume('AT')
                self.skip_comments()
                ident_tok=self.consume('IDENT')
                if ident_tok is None:
                    self.pos=saved
                    return None
                return {'type':'at_pattern','pattern':pat,'at_name':{'name':ident_tok.text,'line':ident_tok.line,'col':ident_tok.col,'end_col':ident_tok.end_col,'skip': (ident_tok.line-1) in self.skip_lines}}
            else:
                return pat
        return None

    def parse_pattern(self):
        self.skip_comments()
        l_brace=self.consume('L_BRACE')
        if l_brace is None:
            return None
        entries=[]
        has_ellipsis=False
        while True:
            self.skip_comments()
            tok=self.peek()
            if tok is None:
                break
            if tok.type=='R_BRACE':
                self.consume('R_BRACE')
                break
            if tok.type=='ELLIPSIS':
                has_ellipsis=True
                self.consume('ELLIPSIS')
                self.skip_comments()
                if self.peek() and self.peek().type=='COMMA':
                    self.consume('COMMA')
                continue
            if tok.type=='IDENT':
                ident_tok=self.consume('IDENT')
                self.skip_comments()
                default_expr=None
                if self.peek() and self.peek().type=='QUESTION':
                    self.consume('QUESTION')
                    self.skip_comments()
                    default_expr=self.parse_expr()
                self.skip_comments()
                if self.peek() and self.peek().type=='COMMA':
                    self.consume('COMMA')
                is_skipped = (ident_tok.line-1) in self.skip_lines
                entries.append({'name':ident_tok.text,'line':ident_tok.line,'col':ident_tok.col,'end_col':ident_tok.end_col,'default':default_expr,'skip':is_skipped,'tok':ident_tok})
                continue
            if tok.type=='COMMA':
                self.consume('COMMA')
                continue
            # unexpected
            self.pos+=1
        return {'type':'pattern','entries':entries,'ellipsis':has_ellipsis,'line':l_brace.line}

    def parse_list(self):
        self.consume('L_BRACK')
        elems=[]
        while True:
            self.skip_comments()
            tok=self.peek()
            if tok is None or tok.type=='R_BRACK':
                self.consume('R_BRACK')
                break
            expr=self.parse_expr()
            if expr:
                elems.append(expr)
        return {'type':'list','elems':elems}

def collect_refs(node):
    if node is None:
        return set()
    t=node.get('type')
    if t=='var':
        return {node['name']}
    if t=='let':
        s=set()
        for b in node['bindings']:
            if b['type']=='binding':
                if b['expr']:
                    s.update(collect_refs(b['expr']))
            elif b['type']=='inherit':
                if b['from']:
                    s.update(collect_refs(b['from']))
        s.update(collect_refs(node['body']))
        return s
    if t=='with':
        s=set()
        s.update(collect_refs(node['expr']))
        s.update(collect_refs(node['body']))
        return s
    if t=='lambda':
        s=set()
        param=node['param']
        if param['type']=='pattern':
            for e in param['entries']:
                if e['default']:
                    s.update(collect_refs(e['default']))
        elif param['type']=='at_pattern':
            pat=param.get('pattern')
            if pat:
                if pat['type']=='pattern':
                    for en in pat['entries']:
                        if en['default']:
                            s.update(collect_refs(en['default']))
        s.update(collect_refs(node['body']))
        return s
    if t=='attrset':
        s=set()
        for b in node['bindings']:
            if b['type']=='inherit':
                if b['from']:
                    s.update(collect_refs(b['from']))
                if b['from'] is None:
                    for ident in b['idents']:
                        s.add(ident['name'])
            elif b['type']=='attr_assign':
                if b['expr']:
                    s.update(collect_refs(b['expr']))
                # also need interps in attrpath?
                # attrpath interps are stored in b['path']['interps']?
                # our attrpath returns dict with interps
                ap=b.get('path')
                if isinstance(ap, dict) and 'interps' in ap:
                    for inter in ap['interps']:
                        s.update(collect_refs(inter))
        return s
    if t=='list':
        s=set()
        for e in node['elems']:
            s.update(collect_refs(e))
        return s
    if t=='app':
        s=set()
        s.update(collect_refs(node['func']))
        for a in node['args']:
            s.update(collect_refs(a))
        return s
    if t=='string_interp':
        s=set()
        for e in node['exprs']:
            s.update(collect_refs(e))
        return s
    if t=='if':
        s=set()
        s.update(collect_refs(node['cond']))
        s.update(collect_refs(node['then']))
        s.update(collect_refs(node['else']))
        return s
    if t=='assert':
        s=set()
        s.update(collect_refs(node['cond']))
        s.update(collect_refs(node['body']))
        return s
    return set()

