def get_attrset_keys(node):
    # if node is attrset literal, return list of keys (strings) that are simple idents
    if node is None:
        return None
    if node.get('type')!='attrset':
        return None
    keys=[]
    for b in node['bindings']:
        if b['type']=='attr_assign':
            path=b.get('path')
            if isinstance(path, dict):
                names=path.get('names',[])
                if names:
                    first=names[0]
                    if first not in ('<string>','<interp>'):
                        keys.append(first)
        elif b['type']=='inherit':
            # inherit without from: keys are idents, but they are bindings inside attrset, not keys? For with { inherit x; }, the keys are x?
            # Actually { inherit x; } means attrset has attr x = outer x, so key is x
            for ident in b['idents']:
                keys.append(ident['name'])
    return keys

