    for idx,l in enumerate(lines, start=1):
        if 'deadnix: skip' in l:
            skip_lines.add(idx)
    state_stack=[{'type':'CODE'}]
    def add_token(t_type, text, sl, sc, el, ec, soff, eoff):
        tokens.append(Token(t_type, text, sl, sc, el, ec, soff, eoff))
    while i<n:
        cur=state_stack[-1]
        if cur['type']=='CODE':
            c=source[i]
            if c in ' \t\r':
                j=i
                while j<n and source[j] in ' \t\r':
                    j+=1
                l = j-i
                col+=l
                offset+=l
                i=j
                continue
            if c=='\n':
                line+=1; col=1; offset+=1; i+=1
                continue
            if c=='#':
                sl=line; sc=col; soff=offset
                j=i
                while j<n and source[j]!='\n':
                    j+=1
                text=source[i:j]
                add_token('COMMENT', text, sl, sc, line, col+len(text), soff, offset+len(text))
                col+=len(text); offset+=len(text); i=j
                continue
            if source[i:i+2]=='/*':
                sl=line; sc=col; soff=offset
                j=i+2
                tmp_line=line
                tmp_col=col+2
                while j<n:
                    if source[j:j+2]=='*/':
                        j+=2
                        break
                    if source[j]=='\n':
                        tmp_line+=1; tmp_col=1
                    else:
                        tmp_col+=1
                    j+=1
                text=source[i:j]
                nl=text.count('\n')
                if nl==0:
                    el=sl; ec=sc+len(text)
                else:
                    el=sl+nl; ec=len(text)-text.rfind('\n')
                add_token('COMMENT_BLOCK', text, sl, sc, el, ec, soff, soff+len(text))
                for ch in text:
                    if ch=='\n':
                        line+=1; col=1
                    else:
                        col+=1
                    offset+=1
                i=j
                continue
            if c=='"':
                sl=line; sc=col; soff=offset
                state_stack.append({'type':'STRING_DQ','start_line':sl,'start_col':sc,'start_offset':soff})
                col+=1; offset+=1; i+=1
                continue
            if source[i:i+2]=="''":
                sl=line; sc=col; soff=offset
                state_stack.append({'type':'IND_STRING','start_line':sl,'start_col':sc,'start_offset':soff})
                col+=2; offset+=2; i+=2
                continue
            if source[i:i+3]=='...':
                sl=line; sc=col; soff=offset
                add_token('ELLIPSIS','...',sl,sc,line,col+3,soff,offset+3)
                col+=3; offset+=3; i+=3
                continue
            if c.isalpha() or c=='_':
                sl=line; sc=col; soff=offset
                j=i
                while j<n and (source[j].isalnum() or source[j] in "_-'"):
                    j+=1
                text=source[i:j]
                ttype=KEYWORDS.get(text,'IDENT')
                add_token(ttype,text,sl,sc,line,col+len(text),soff,offset+len(text))
                col+=len(text); offset+=len(text); i=j
                continue
            if c.isdigit():
                sl=line; sc=col; soff=offset
                j=i
                while j<n and (source[j].isdigit() or source[j]=='.'):
                    j+=1
                text=source[i:j]
                add_token('NUMBER',text,sl,sc,line,col+len(text),soff,offset+len(text))
                col+=len(text); offset+=len(text); i=j
                continue
            sym_map = {
                '{':'L_BRACE',
                '}':'R_BRACE',
                '[':'L_BRACK',
                ']':'R_BRACK',
                '(':'L_PAREN',
                ')':'R_PAREN',
                '=':'EQ',
                ';':'SEMI',
                ':':'COLON',
                ',':'COMMA',
                '.':'DOT',
                '@':'AT',
                '?':'QUESTION',
            }
            if c in sym_map:
                sl=line; sc=col; soff=offset
                if c=='}' and cur.get('is_interp'):
                    if cur.get('brace_depth',0)>0:
                        cur['brace_depth']-=1
                        add_token('R_BRACE',c,sl,sc,line,col+1,soff,offset+1)
                        col+=1; offset+=1; i+=1
                        continue
                    else:
                        add_token('INTERP_END',c,sl,sc,line,col+1,soff,offset+1)
                        col+=1; offset+=1; i+=1
                        state_stack.pop()
                        continue
                if c=='{' and cur.get('is_interp'):
                    cur['brace_depth']=cur.get('brace_depth',0)+1
                add_token(sym_map[c],c,sl,sc,line,col+1,soff,offset+1)
                col+=1; offset+=1; i+=1
                continue
            if c in '+-*/<>!&|':
                sl=line; sc=col; soff=offset
                j=i
                while j<n and source[j] in '+-*/<>!=&|':
                    j+=1
                text=source[i:j]
                add_token('OP',text,sl,sc,line,col+len(text),soff,offset+len(text))
                col+=len(text); offset+=len(text); i=j
                continue
            if c=='$':
                sl=line; sc=col; soff=offset
                add_token('DOLLAR',c,sl,sc,line,col+1,soff,offset+1)
                col+=1; offset+=1; i+=1
                continue
            col+=1; offset+=1; i+=1
            continue
        elif cur['type']=='STRING_DQ':
            if i>=n:
                sl=cur['start_line']; sc=cur['start_col']; soff=cur['start_offset']
                text=source[soff:i]
                add_token('STRING',text,sl,sc,line,col,soff,offset)
                state_stack.pop()
                break
            if source[i]=='\\':
                if i+1<n:
                    if source[i+1]=='\n':
                        line+=1; col=1
                    else:
                        col+=2
                    offset+=2; i+=2
                else:
                    col+=1; offset+=1; i+=1
                continue
            if source[i:i+2]=='${':
                sl=line; sc=col; soff=offset
                add_token('INTERP_START','${',sl,sc,line,col+2,soff,offset+2)
                col+=2; offset+=2; i+=2
                state_stack.append({'type':'CODE','is_interp':True,'brace_depth':0})
                continue
            if source[i]=='"':
                sl=cur['start_line']; sc=cur['start_col']; soff=cur['start_offset']
                text=source[soff:i+1]
                add_token('STRING',text,sl,sc,line,col+1,soff,offset+1)
                col+=1; offset+=1; i+=1
                state_stack.pop()
                continue
            if source[i]=='\n':
                line+=1; col=1; offset+=1; i+=1
            else:
                col+=1; offset+=1; i+=1
            continue
        elif cur['type']=='IND_STRING':
            if i+1<n and source[i:i+2]=="''":
                if source[i:i+3]=="'''":
                    col+=3; offset+=3; i+=3
                    continue
                if i+2<n and source[i+2]=='$' and i+3<n and source[i+3]=='{':
                    col+=2; offset+=2; i+=2
                    continue
                sl=cur['start_line']; sc=cur['start_col']; soff=cur['start_offset']
                text=source[soff:i+2]
                nl=text.count('\n')
                if nl==0:
                    el=sl; ec=sc+len(text)
                else:
                    el=sl+nl; ec=len(text)-text.rfind('\n')
                add_token('STRING',text,sl,sc,el,ec,soff,soff+len(text))
                col+=2; offset+=2; i+=2
                state_stack.pop()
                continue
            if source[i:i+2]=='${':
                sl=line; sc=col; soff=offset
                add_token('INTERP_START','${',sl,sc,line,col+2,soff,offset+2)
                col+=2; offset+=2; i+=2
                state_stack.append({'type':'CODE','is_interp':True,'brace_depth':0})
                continue
            if source[i]=='\n':
                line+=1; col=1; offset+=1; i+=1
            else:
                col+=1; offset+=1; i+=1
            continue
    return tokens, skip_lines, lines

class Parser:
    def __init__(self, tokens, source, lines, skip_lines):
        self.tokens=tokens
        self.pos=0
        self.source=source
        self.lines=lines
        self.skip_lines=skip_lines
        self._attrpath_interps=[]

    def peek(self, off=0):
        idx=self.pos+off
        if idx < len(self.tokens):
            return self.tokens[idx]
        return None

    def consume(self, typ=None):
        t=self.peek()
        if t is None:
            return None
        if typ and t.type!=typ:
            return None
        self.pos+=1
        return t

    def skip_comments(self):
        while True:
            t=self.peek()
            if t and t.type in ('COMMENT','COMMENT_BLOCK'):
                self.pos+=1
            else:
                break

    def parse(self):
        self.skip_comments()
        if self.pos>=len(self.tokens):
            return None
        return self.parse_expr()

    def parse_expr(self):
        self.skip_comments()
        t=self.peek()
        if t is None:
            return None
        if t.type=='LET':
            return self.parse_let()
        if t.type=='WITH':
            return self.parse_with()
        saved=self.pos
        param=self.try_parse_lambda_param()
        if param is not None:
            self.skip_comments()
            nxt=self.peek()
            if nxt and nxt.type=='COLON':
                self.consume('COLON')
                body=self.parse_expr()
                return {'type':'lambda','param':param,'body':body}
            self.pos=saved
        expr=self.parse_term()
        if expr is None:
            return None
        args=[]
        while True:
            self.skip_comments()
            nxt=self.peek()
            if nxt is None:
                break
            if nxt.type in ('IN','SEMI','R_BRACE','R_BRACK','R_PAREN','COMMA','ELSE','THEN'):
                break
            if nxt.type in ('IDENT','L_BRACE','L_BRACK','L_PAREN','STRING','NUMBER','REC','IF','ASSERT','INTERP_START'):
                term=self.parse_term()
                if term:
                    args.append(term)
                else:
                    break
            else:
                break
        if args:
            return {'type':'app','func':expr,'args':args}
        return expr

    def parse_term(self):
        self.skip_comments()
        t=self.peek()
        if t is None:
            return None
        if t.type=='L_BRACE':
            return self.parse_attrset()
        if t.type=='L_BRACK':
            return self.parse_list()
        if t.type=='L_PAREN':
            self.consume('L_PAREN')
            inner=self.parse_expr()
            self.skip_comments()
            self.consume('R_PAREN')
            return inner
        if t.type=='IDENT':
            ident=self.consume('IDENT')
            path=[ident.text]
            while True:
                self.skip_comments()
                nxt=self.peek()
                if nxt and nxt.type=='DOT':
                    self.consume('DOT')
                    nn=self.peek()
                    if nn and nn.type=='IDENT':
                        self.consume('IDENT')
                        path.append(nn.text)
                    elif nn and nn.type=='STRING':
                        self.consume('STRING')
                        path.append('<string>')
                    else:
                        break
                else:
                    break
            return {'type':'var','name':ident.text,'line':ident.line,'col':ident.col,'end_col':ident.end_col,'path':path,'tok':ident}
        if t.type=='INTERP_START':
            self.consume('INTERP_START')
            expr=self.parse_expr()
            self.skip_comments()
            self.consume('INTERP_END')
            return expr
        if t.type=='STRING':
            return self.parse_string_with_interps()
        if t.type=='NUMBER':
            self.consume('NUMBER')
            return {'type':'literal'}
        if t.type=='REC':
            self.consume('REC')
            self.skip_comments()
            if self.peek() and self.peek().type=='L_BRACE':
                return self.parse_attrset(rec=True)
            return {'type':'rec'}
        if t.type=='IF':
            self.consume('IF')
            cond=self.parse_expr()
            self.skip_comments()
            self.consume('THEN')
            then_e=self.parse_expr()
            self.skip_comments()
            self.consume('ELSE')
            else_e=self.parse_expr()
            return {'type':'if','cond':cond,'then':then_e,'else':else_e}
        if t.type=='ASSERT':
            self.consume('ASSERT')
            cond=self.parse_expr()
            self.skip_comments()
            self.consume('SEMI')
            body=self.parse_expr()
            return {'type':'assert','cond':cond,'body':body}
        self.pos+=1
        return None

    def parse_string_with_interps(self):
        exprs=[]
        while True:
            self.skip_comments()
            t=self.peek()
            if t is None:
                break
            if t.type=='STRING':
                self.consume('STRING')
                continue
            if t.type=='INTERP_START':
                self.consume('INTERP_START')
                e=self.parse_expr()
                if e:
                    exprs.append(e)
                self.skip_comments()
                self.consume('INTERP_END')
                continue
            break
        if exprs:
            return {'type':'string_interp','exprs':exprs}
        return {'type':'string'}

    def parse_attrset(self, rec=False):
        self.skip_comments()
        start=self.consume('L_BRACE')
        if start is None:
            return None
        bindings=[]
        while True:
            self.skip_comments()
            t=self.peek()
            if t is None:
                break
            if t.type=='R_BRACE':
                self.consume('R_BRACE')
                break
            if t.type=='INHERIT':
                inh=self.parse_inherit()
                if inh:
                    bindings.append(inh)
                continue
            attrpath=self.parse_attrpath()
            if attrpath is None:
                self.pos+=1
                continue
            self.skip_comments()
            eq=self.consume('EQ')
            if eq is None:
                while self.peek() and self.peek().type not in ('SEMI','R_BRACE'):
                    self.pos+=1
                if self.peek() and self.peek().type=='SEMI':
                    self.consume('SEMI')
                continue
            self.skip_comments()
            expr=self.parse_expr()
            self.skip_comments()
            self.consume('SEMI')
            bindings.append({'type':'attr_assign','path':attrpath,'expr':expr})
        return {'type':'attrset','rec':rec,'bindings':bindings,'line':start.line if start else 0, 'start_offset': start.offset if start else 0, 'end_offset': self.tokens[self.pos-1].end_offset if self.pos>0 else 0}

    def parse_attrpath(self):
        self.skip_comments()
        path_names=[]
        path_toks=[]
        interps=[]
        while True:
            self.skip_comments()
            t=self.peek()
            if t is None:
                break
            if t.type=='IDENT':
                tok=self.consume('IDENT')
                path_names.append(tok.text)
                path_toks.append(tok)
            elif t.type=='STRING':
                self.consume('STRING')
                path_names.append('<string>')
                path_toks.append(t)
            elif t.type=='INTERP_START':
                self.consume('INTERP_START')
                e=self.parse_expr()
                self.consume('INTERP_END')
                path_names.append('<interp>')
                path_toks.append(t)
                if e:
                    interps.append(e)
            else:
                break
            self.skip_comments()
            nxt=self.peek()
            if nxt and nxt.type=='DOT':
                self.consume('DOT')
                continue
            break
        if path_names:
            return {'names':path_names,'toks':path_toks,'interps':interps}
        return None

    def parse_inherit(self):
        self.skip_comments()
        inherit_tok=self.consume('INHERIT')
        if inherit_tok is None:
            return None
        self.skip_comments()
        from_expr=None
        if self.peek() and self.peek().type=='L_PAREN':
            self.consume('L_PAREN')
            from_expr=self.parse_expr()
            self.skip_comments()
            self.consume('R_PAREN')
        idents=[]
        while True:
            self.skip_comments()
            tok=self.peek()
            if tok and tok.type=='IDENT':
                id_tok=self.consume('IDENT')
                is_skipped = (id_tok.line-1) in self.skip_lines
                idents.append({'name':id_tok.text,'line':id_tok.line,'col':id_tok.col,'end_col':id_tok.end_col,'skip':is_skipped,'tok':id_tok})
            else:
                break
        self.skip_comments()
        self.consume('SEMI')
        return {'type':'inherit','from':from_expr,'idents':idents,'line':inherit_tok.line, 'start_offset': inherit_tok.offset, 'end_offset': self.tokens[self.pos-1].end_offset if self.pos>0 else inherit_tok.end_offset}

    def parse_let(self):
        let_tok=self.consume('LET')
        bindings=[]
        while True:
            self.skip_comments()
            tok=self.peek()
            if tok is None:
                break
            if tok.type=='IN':
                self.consume('IN')
                break
            if tok.type=='INHERIT':
                inh=self.parse_inherit()
                if inh:
                    bindings.append(inh)
                continue
            if tok and tok.type not in ('IDENT','STRING'):
                self.pos+=1
                continue
            attrpath=self.parse_attrpath()
            if attrpath is None:
                self.pos+=1
                continue
            self.skip_comments()
            eq=self.consume('EQ')
            if eq is None:
                while self.peek() and self.peek().type not in ('SEMI','IN'):
                    self.pos+=1
                if self.peek() and self.peek().type=='SEMI':
                    self.consume('SEMI')
                continue
            self.skip_comments()
            expr=self.parse_expr()
            self.skip_comments()
            semi_tok=self.peek()
            if semi_tok and semi_tok.type=='SEMI':
                self.consume('SEMI')
            first_name = attrpath['names'][0] if attrpath['names'] else None
            first_tok = attrpath['toks'][0] if attrpath['toks'] else None
            if first_name and first_name not in ('<string>','<interp>'):
                line=first_tok.line if first_tok else 0
                col=first_tok.col if first_tok else 0
                end_col=first_tok.end_col if first_tok else 0
                is_skipped = (line-1) in self.skip_lines
                bindings.append({'type':'binding','name':first_name,'expr':expr,'line':line,'col':col,'end_col':end_col,'skip':is_skipped,'attrpath':attrpath,'tok':first_tok,'start_offset':first_tok.offset if first_tok else 0,'end_offset': semi_tok.end_offset if semi_tok and hasattr(semi_tok,'end_offset') else 0})
        body=self.parse_expr()
        return {'type':'let','bindings':bindings,'body':body,'line':let_tok.line if let_tok else 0,'start_offset':let_tok.offset if let_tok else 0}

    def try_parse_lambda_param(self):
        saved=self.pos
        self.skip_comments()
        tok=self.peek()
        if tok is None:
            return None
        if tok.type=='IDENT':
            ident_tok=self.consume('IDENT')
            self.skip_comments()
            nxt=self.peek()
            if nxt and nxt.type=='AT':
                self.consume('AT')
                self.skip_comments()
                nxt2=self.peek()
                if nxt2 and nxt2.type=='L_BRACE':
                    pat=self.parse_pattern()
                    if pat:
                        return {'type':'at_pattern','at_name':{'name':ident_tok.text,'line':ident_tok.line,'col':ident_tok.col,'end_col':ident_tok.end_col,'skip': (ident_tok.line-1) in self.skip_lines,'tok':ident_tok},'pattern':pat}
                elif nxt2 and nxt2.type=='IDENT':
                    ident2=self.consume('IDENT')
                    pat={'type':'simple','name':ident2.text,'line':ident2.line,'col':ident2.col,'end_col':ident2.end_col,'skip': (ident2.line-1) in self.skip_lines,'tok':ident2}
                    return {'type':'at_pattern','at_name':{'name':ident_tok.text,'line':ident_tok.line,'col':ident_tok.col,'end_col':ident_tok.end_col,'skip': (ident_tok.line-1) in self.skip_lines,'tok':ident_tok},'pattern':pat}
                else:
                    self.pos=saved
                    return None
            else:
                return {'type':'simple','name':ident_tok.text,'line':ident_tok.line,'col':ident_tok.col,'end_col':ident_tok.end_col,'skip': (ident_tok.line-1) in self.skip_lines,'tok':ident_tok}
        if tok.type=='L_BRACE':
            pat=self.parse_pattern()
            if pat is None:
                self.pos=saved
                return None
            self.skip_comments()
            nxt=self.peek()
            if nxt and nxt.type=='AT':
                self.consume('AT')
                self.skip_comments()
                ident_tok=self.consume('IDENT')
                if ident_tok is None:
                    self.pos=saved
                    return None
                return {'type':'at_pattern','pattern':pat,'at_name':{'name':ident_tok.text,'line':ident_tok.line,'col':ident_tok.col,'end_col':ident_tok.end_col,'skip': (ident_tok.line-1) in self.skip_lines,'tok':ident_tok}}
            else:
                return pat
        return None

    def parse_pattern(self):
        self.skip_comments()
        l_brace=self.consume('L_BRACE')
        if l_brace is None:
            return None
        entries=[]
        has_ellipsis=False
        while True:
            self.skip_comments()
            tok=self.peek()
            if tok is None:
                break
            if tok.type=='R_BRACE':
                self.consume('R_BRACE')
                break
            if tok.type=='ELLIPSIS':
                has_ellipsis=True
                self.consume('ELLIPSIS')
                self.skip_comments()
                if self.peek() and self.peek().type=='COMMA':
                    self.consume('COMMA')
                continue
            if tok.type=='IDENT':
                ident_tok=self.consume('IDENT')
                self.skip_comments()
                default_expr=None
                if self.peek() and self.peek().type=='QUESTION':
                    self.consume('QUESTION')
                    self.skip_comments()
                    default_expr=self.parse_expr()
                self.skip_comments()
                if self.peek() and self.peek().type=='COMMA':
                    self.consume('COMMA')
                is_skipped = (ident_tok.line-1) in self.skip_lines
                entries.append({'name':ident_tok.text,'line':ident_tok.line,'col':ident_tok.col,'end_col':ident_tok.end_col,'default':default_expr,'skip':is_skipped,'tok':ident_tok})
                continue
            if tok.type=='COMMA':
                self.consume('COMMA')
                continue
            self.pos+=1
        return {'type':'pattern','entries':entries,'ellipsis':has_ellipsis,'line':l_brace.line,'start_offset':l_brace.offset,'end_offset': self.tokens[self.pos-1].end_offset if self.pos>0 else l_brace.end_offset,'l_brace':l_brace,'r_brace_offset': self.tokens[self.pos-1].end_offset if self.pos>0 else 0}

    def parse_list(self):
        self.consume('L_BRACK')
        elems=[]
        while True:
            self.skip_comments()
            tok=self.peek()
            if tok is None or tok.type=='R_BRACK':
                self.consume('R_BRACK')
                break
            expr=self.parse_expr()
            if expr:
                elems.append(expr)
        return {'type':'list','elems':elems}

def get_attrset_keys(node):
    if node is None or node.get('type')!='attrset':
        return None
    keys=[]
    for b in node['bindings']:
        if b['type']=='attr_assign':
            path=b.get('path')
            if isinstance(path, dict):
                names=path.get('names',[])
                if names:
                    first=names[0]
                    if first not in ('<string>','<interp>'):
                        keys.append(first)
        elif b['type']=='inherit':
            for ident in b['idents']:
                keys.append(ident['name'])
    return keys

class Analyzer:
    def __init__(self, source, lines, skip_lines, options):
        self.source=source
        self.lines=lines
        self.skip_lines=skip_lines
        self.options=options
        self.findings=[]

    def analyze(self, node, scope_stack=None, with_shadows=None):
        if scope_stack is None:
            scope_stack=[]
        if with_shadows is None:
            with_shadows=[]
        if node is None:
            return set()
        t=node.get('type')
        if t=='var':
            name=node['name']
            for shadow in reversed(with_shadows):
                if shadow is not None and name in shadow:
                    return set()
            return {name}
        if t=='let':
            let_bindings=[]
            name_to_indices={}
            for b in node['bindings']:
                if b['type']=='binding':
                    idx=len(let_bindings)
