#!/usr/bin/env python3
import sys, os, re, json, pathlib

VERSION = "deadnix 1.3.1"

class Token:
    __slots__ = ('type','text','line','col','end_line','end_col','offset','end_offset')
    def __init__(self, type_, text, line, col, end_line, end_col, offset, end_offset):
        self.type=type_
        self.text=text
        self.line=line
        self.col=col
        self.end_line=end_line
        self.end_col=end_col
        self.offset=offset
        self.end_offset=end_offset

KEYWORDS = {
    'let':'LET',
    'in':'IN',
    'inherit':'INHERIT',
    'rec':'REC',
    'with':'WITH',
    'if':'IF',
    'then':'THEN',
    'else':'ELSE',
    'assert':'ASSERT',
    'or':'OR_KW',
}

def lex(source):
    tokens=[]
    i=0
    line=1
    col=1
    offset=0
    n=len(source)
    lines = source.splitlines()
    skip_lines=set()
