        cur=state_stack[-1]
        if cur['type']=='CODE':
            c=source[i]
            if c in ' \t\r':
                j=i
                while j<n and source[j] in ' \t\r':
                    j+=1
                l = j-i
                col+=l
                offset+=l
                i=j
                continue
            if c=='\n':
                line+=1; col=1; offset+=1; i+=1
                continue
            if c=='#':
                sl=line; sc=col; soff=offset
                j=i
                while j<n and source[j]!='\n':
                    j+=1
                text=source[i:j]
                add_token('COMMENT', text, sl, sc, line, col+len(text), soff, offset+len(text))
                col+=len(text); offset+=len(text); i=j
                continue
            if source[i:i+2]=='/*':
                sl=line; sc=col; soff=offset
                j=i+2
                tmp_line=line
                tmp_col=col+2
                while j<n:
                    if source[j:j+2]=='*/':
