    excludes=[]
    file_paths=[]
    # Manual parsing
    i=1
    n=len(argv)
    # State for handling -- delimiter: after encountering "--" as standalone, all remaining are file_paths
    # Also handle --exclude variadic
    while i<n:
        arg=argv[i]
        if arg=='--':
            # All remaining are file_paths
            file_paths.extend(argv[i+1:])
