                    print(f"error: unexpected argument '-{ch}' found\n\n  tip: to pass '-{ch}' as a value, use '-- -{ch}'\n\nUsage: executable [OPTIONS] [FILE_PATHS]...\n\nFor more information, try '--help'.", file=sys.stderr)
                    sys.exit(2)
                j+=1
            i+=1
            continue
        if arg.startswith('-'):
