                # Our current results has line/col/message
                # So output
                json_outputs.append(json.dumps({"file":fp,"results":results}))
            else:
                # human-readable, collect for later rendering per file
                if not options['quiet']:
                    human_files.append((fp, src, detailed))
        else:
            # No findings, nothing to output for json (as observed)
            # For human, nothing either
            pass

        # Edit if needed
        if options['edit'] and src is not None:
            # Only edit if there are findings that are editable (detailed not empty)
            if detailed:
                # For edit, we need to edit file based on detailed findings
                # But also need to consider that editing should happen even if quiet? Yes, earlier we saw -q -e still edited.
                # So edit file
                try:
                    edit_file(fp, detailed, options)
                except Exception as e:
                    import traceback
                    traceback.print_exc()

    # Output
    use_color = not os.environ.get('NO_COLOR')
    if options['output_format']=='json':
        for line in json_outputs:
            print(line)
    else:
        if not options['quiet']:
            # Render human
            # For each file, we need to render
            # Our render_human function expects list of (file_path, source, detailed)
            # But source may have been edited already? For -e, original binary still printed warning report before editing? In earlier test, -e printed warning report (human) and also edited. So report should be based on original source before edit, not after. Our human_files collected before edit, so we have original source.

            # Now render
            output = render_human(human_files, use_color)
            if output:
                print(output)

    # Fail handling
    if options['fail'] and has_findings:
        sys.exit(1)
    else:
        sys.exit(0)

def render_human_one_file(file_path, source, findings, use_color):
    if not findings:
        return ""
    sorted_findings=sorted(findings, key=lambda x: (x['line'], x['col']))
    src_lines=source.splitlines()
    total_lines=len(src_lines) if src_lines else 1
    width=len(str(total_lines)) + 1
    first=sorted_findings[0]
    indent=" "*(width+1)
    if use_color:
        header = f"{indent}\x1b[38;5;246m╭\x1b[0m\x1b[38;5;246m─\x1b[0m\x1b[38;5;246m[\x1b[0m{file_path}:{first['line']}:{first['col']}\x1b[38;5;246m]\x1b[0m"
    else:
        header = f"{indent}╭─[{file_path}:{first['line']}:{first['col']}]"
    by_line=defaultdict(list)
    for f in sorted_findings:
        by_line[f['line']].append(f)
    output_lines=[]
    output_lines.append(header)
    for line_no in sorted(by_line.keys()):
        if line_no-1 < len(src_lines):
            src_text=src_lines[line_no-1]
        else:
            src_text=""
        # source line
        if use_color:
            # For simplicity, we will not syntax highlight source content fully, but we will highlight unused identifiers?
            # We'll attempt to highlight: find all findings on this line and color their identifier text
            # We'll need to build colored source line: we have src_text, and we have findings with col,end_col
            # We'll sort findings by col ascending and apply colors
            # For each finding, its identifier from col to end_col should be colored based on type
            # We'll build colored line piecewise

            # Create list of segments
            # We'll sort line_findings by col ascending
            line_findings_sorted_asc=sorted(by_line[line_no], key=lambda x: x['col'])
            colored_src=""
            last_idx=0
            for f in line_findings_sorted_asc:
                # f col is 1-indexed, convert to 0-indexed in src_text
                start_col=f['col']-1
                end_col=f['end_col']-1  # end exclusive? Actually end_col is exclusive, so slice [start_col:end_col]
                # Ensure within src_text
                if start_col <0:
                    start_col=0
                if end_col > len(src_text):
                    end_col=len(src_text)
                if start_col > len(src_text):
                    continue
                # Append uncolored part before
                if start_col>last_idx:
                    colored_src+=src_text[last_idx:start_col]
                # Colored part
                ident_text=src_text[start_col:end_col]
                # Determine color
                if 'let' in f['type']:
                    color=31
                elif 'lambda_pattern' in f['type']:
                    color=35
                elif 'lambda_arg' in f['type']:
                    color=36
                else:
                    color=31
                colored_src+=f"\x1b[{color}m{ident_text}\x1b[0m"
                last_idx=end_col
            # Append rest
            if last_idx < len(src_text):
                colored_src+=src_text[last_idx:]
            # Now line number and gutter grey
            line_no_str = f"\x1b[38;5;246m{line_no:>{width}} │\x1b[0m"
            output_lines.append(f"{line_no_str}{colored_src}")
        else:
            line_no_str = f"{line_no:>{width}} │"
            output_lines.append(f"{line_no_str}{src_text}")
        # findings on this line sorted descending by middle
        line_findings=by_line[line_no]
        for f in line_findings:
            f['_middle'] = (f['col'] + f['end_col']) // 2
            f['_end'] = f['end_col']
        line_findings_sorted=sorted(line_findings, key=lambda x: x['_middle'], reverse=True)
        dashes=[]
        for idx, f in enumerate(line_findings_sorted):
            if idx==0:
                d=f['_end'] - f['_middle']
                if d<=0:
                    d=1
                dashes.append(d)
            else:
                prev_middle=line_findings_sorted[idx-1]['_middle']
                cur_middle=f['_middle']
                d=(prev_middle - cur_middle) + dashes[idx-1]
                dashes.append(d)
        for idx, f in enumerate(line_findings_sorted):
            middle=f['_middle']
            dash=dashes[idx]
            remaining=line_findings_sorted[idx+1:]
            buf_len = middle -1 + dash
            buf=[' '] * buf_len
            for rem in remaining:
                m=rem['_middle']
                if 0 <= m-1 < len(buf):
                    buf[m-1]='│'
            if 0 <= middle-1 < len(buf):
                buf[middle-1]='╰'
            for k in range(dash):
                pos=middle-1+1+k
                if 0 <= pos < len(buf):
                    buf[pos]='─'
            after_str=''.join(buf)
            if use_color:
                # Build colored after_str
                # Need to color bars based on remaining findings' types and ╰/─ based on current
                # We'll build with colors
                colored_after=[]
                for pos,ch in enumerate(buf):
                    if ch==' ':
                        colored_after.append(' ')
                    elif ch=='│':
                        # find matching remaining
                        match=None
                        for rem in remaining:
                            if rem['_middle']-1==pos:
                                match=rem
                                break
                        if match:
                            col_code = 31 if 'let' in match['type'] else (35 if 'lambda_pattern' in match['type'] else 36)
                            colored_after.append(f"\x1b[{col_code}m│\x1b[0m")
                        else:
                            colored_after.append('│')
                    elif ch=='╰':
                        col_code = 31 if 'let' in f['type'] else (35 if 'lambda_pattern' in f['type'] else 36)
                        colored_after.append(f"\x1b[{col_code}m╰\x1b[0m")
                    elif ch=='─':
                        col_code = 31 if 'let' in f['type'] else (35 if 'lambda_pattern' in f['type'] else 36)
                        colored_after.append(f"\x1b[{col_code}m─\x1b[0m")
                    else:
                        colored_after.append(ch)
                after_str_colored=''.join(colored_after)
                ptr_indent = f"{' '*(width+1)}\x1b[38;5;240m│\x1b[0m"
                output_lines.append(f"{ptr_indent}{after_str_colored} {f['message']}")
            else:
                output_lines.append(f"{' '*(width+1)}│{after_str} {f['message']}")
    return "\n".join(output_lines)

def render_human(files_findings, use_color):
    output=[]
    warn_text = "\x1b[33mWarning:\x1b[0m Unused declarations were found." if use_color else "Warning: Unused declarations were found."
    for file_path, source, findings in files_findings:
        if not findings:
            continue
        report=render_human_one_file(file_path, source, findings, use_color)
        if report:
            output.append(warn_text)
            output.append(report)
    return "\n".join(output)

def find_nix_files(paths, hidden=False, excludes=None):
    if excludes is None:
        excludes=[]
    excl_abs=[]
    for p in excludes:
        try:
            if os.path.isabs(p):
                excl_abs.append(os.path.normpath(p))
            else:
                excl_abs.append(os.path.normpath(os.path.join(os.getcwd(), p)))
        except:
            excl_abs.append(p)
    def is_excluded(file_path):
        fp_abs=os.path.normpath(os.path.abspath(file_path))
        for ex in excl_abs:
            if fp_abs==ex:
                return True
            if fp_abs.startswith(ex + os.sep):
                return True
        return False
    collected=[]
    for p in paths:
        if not os.path.exists(p):
            collected.append(p)
            continue
        if os.path.isfile(p):
            collected.append(p)
        elif os.path.isdir(p):
            for root, dirs, files in os.walk(p, topdown=True):
                if not hidden:
                    dirs[:] = [d for d in dirs if not d.startswith('.')]
                # Sort dirs and files for determinism? Use alphabetical
                dirs.sort()
                files.sort()
                for f in files:
                    if not hidden and f.startswith('.'):
                        continue
                    if not f.endswith('.nix'):
                        continue
                    full=os.path.join(root, f)
                    if is_excluded(full):
                        continue
                    collected.append(full)
        else:
            collected.append(p)
    return collected

def analyze_source(source, options):
    tokens, skip_lines, lines = lex(source)
    parser=Parser(tokens, source, lines, skip_lines)
    ast=parser.parse()
    analyzer=Analyzer(source, lines, skip_lines, options)
    try:
        analyzer.analyze(ast)
    except Exception as e:
        import traceback
        traceback.print_exc()
    findings_sorted=sorted(analyzer.findings, key=lambda x: (x['line'], x['col']))
    return findings_sorted, source, lines, skip_lines, tokens, ast

def analyze_file(path, options):
    try:
        source=pathlib.Path(path).read_text(encoding='utf-8')
    except FileNotFoundError:
        return None, [{"message":"No such file or directory (os error 2)"}], [], "", [], []
    except Exception as e:
        return None, [{"message":str(e)}], [], "", [], []
    findings, src, src_lines, skip_lines, tokens, ast = analyze_source(source, options)
    results=[]
    for f in findings:
        results.append({'line':f['line'],'column':f['col'],'endColumn':f['end_col'],'message':f['message']})
    return src, results, findings, src_lines, tokens, ast

def edit_file(path, findings_detailed, options):
    source = pathlib.Path(path).read_text(encoding='utf-8')
    if not findings_detailed:
        return
    tokens, skip_lines, lines = lex(source)
    parser=Parser(tokens, source, lines, skip_lines)
    ast=parser.parse()
    # Collect nodes
    let_nodes=[]
    lambda_nodes=[]
    def collect_nodes(node):
        if node is None:
            return
        t=node.get('type')
        if t=='let':
            let_nodes.append(node)
            for b in node['bindings']:
                if b['type']=='binding':
                    if b['expr']:
                        collect_nodes(b['expr'])
                elif b['type']=='inherit':
                    if b['from']:
                        collect_nodes(b['from'])
            collect_nodes(node['body'])
        elif t=='lambda':
            lambda_nodes.append(node)
            param=node['param']
            if param['type']=='pattern':
                for e in param['entries']:
                    if e['default']:
                        collect_nodes(e['default'])
            elif param['type']=='at_pattern':
                pat=param.get('pattern')
                if pat and pat['type']=='pattern':
                    for e in pat['entries']:
                        if e['default']:
                            collect_nodes(e['default'])
            collect_nodes(node['body'])
        elif t=='with':
            collect_nodes(node['expr'])
            collect_nodes(node['body'])
        elif t=='attrset':
            for b in node['bindings']:
                if b['type']=='attr_assign':
                    if b['expr']:
                        collect_nodes(b['expr'])
                elif b['type']=='inherit':
                    if b['from']:
                        collect_nodes(b['from'])
        elif t=='list':
            for e in node['elems']:
                collect_nodes(e)
        elif t=='app':
            collect_nodes(node['func'])
            for a in node['args']:
                collect_nodes(a)
        elif t=='string_interp':
            for e in node['exprs']:
                collect_nodes(e)
        elif t=='if':
            collect_nodes(node['cond'])
            collect_nodes(node['then'])
            collect_nodes(node['else'])
        elif t=='assert':
            collect_nodes(node['cond'])
            collect_nodes(node['body'])
    collect_nodes(ast)
    finding_keys=set()
    for f in findings_detailed:
        if f['type'] in ('let','let_used','lambda_pattern','lambda_pattern_used'):
            finding_keys.add((f['line'],f['col'],f['name']))
    edits=[]
    # lambda arg rename
    for f in findings_detailed:
        if f['type']=='lambda_arg':
            tok=f['binding'].get('tok')
            if tok:
                start=tok.offset
                end=tok.end_offset
                new_name='_' + f['name'] if not f['name'].startswith('_') else f['name']
                edits.append((start,end,new_name))
    # let handling
    for let_node in let_nodes:
        unused_in_this=[]
        for b in let_node['bindings']:
            if b['type']=='binding':
                key=(b['line'],b['col'],b['name'])
                if key in finding_keys:
                    unused_in_this.append(b)
            elif b['type']=='inherit':
                remaining=[]
                for ident in b['idents']:
                    key=(ident['line'],ident['col'],ident['name'])
                    if key not in finding_keys:
                        remaining.append(ident)
                if len(remaining)==0:
                    unused_in_this.append(b)
                elif len(remaining)<len(b['idents']):
                    # partial inherit
                    start=b.get('start_offset',0)
                    semi_pos=source.find(';', start)
                    if semi_pos!=-1:
                        end=semi_pos+1
                        # reconstruct
                        orig_text=source[start:end]
                        from_text=""
                        if b['from'] is not None:
                            lpar=orig_text.find('(')
                            rpar=orig_text.find(')', lpar)
                            if lpar!=-1 and rpar!=-1:
                                from_text=orig_text[lpar:rpar+1]
                        if from_text:
                            new_text=f"inherit {from_text} {' '.join([i['name'] for i in remaining])};"
                        else:
                            new_text=f"inherit {' '.join([i['name'] for i in remaining])};"
                        edits.append((start,end,new_text))
        total_bindings=len(let_node['bindings'])
        if len(unused_in_this)==total_bindings and total_bindings>0:
            let_start=let_node.get('start_offset',0)
            # find "in" after let_start
            m=re.search(r'\bin\b', source[let_start:])
            if m:
                in_start=let_start+m.start()
                in_end=let_start+m.end()
                body_start=in_end
                while body_start < len(source) and source[body_start] in ' \t\r\n':
                    body_start+=1
                edits_filtered=[]
                for e in edits:
                    s=e[0]
                    if s==let_start and e[2]=="":
                        edits_filtered.append(e)
                    elif let_start <= s < body_start:
                        continue
                    else:
                        edits_filtered.append(e)
                edits=edits_filtered
                edits.append((let_start, body_start, ""))
        else:
            for b in unused_in_this:
                if b['type']=='binding':
                    tok=b.get('tok')
                    if tok:
                        start=tok.offset
                        # find semicolon
                        semi_pos=source.find(';', start)
                        if semi_pos!=-1:
                            end=semi_pos+1
                            j=end
                            while j < len(source) and source[j] in ' \t':
                                j+=1
                            line_no=b['line']
                            line_text=lines[line_no-1] if line_no-1 < len(lines) else ""
                            # check if alone on line
                            line_start=source.rfind('\n', 0, start)+1
                            prefix=source[line_start:start]
                            if prefix.strip()=='' or prefix.strip()=='let':
                                after=source[end:]
                                nl=after.find('\n')
                                if nl!=-1:
                                    between=after[:nl]
                                    if between.strip()=='':
                                        end=end+nl+1
                                        start=line_start
                            else:
                                end=j
                            edits.append((start,end,""))
                if b['type']=='inherit':
                    # fully unused inherit removal already handled? For case where all idents unused but not all bindings in let, we need to remove whole inherit
                    # That case was added to unused_in_this as inherit, but we didn't add edit for it yet (since we only handled partial above)
                    # So add removal for fully unused inherits
                    # Check if this inherit is fully unused (all idents removed)
                    # We already know remaining==0 for those, but we didn't add edit for full removal in else branch? Let's add
                    start=b.get('start_offset',0)
                    semi_pos=source.find(';', start)
                    if semi_pos!=-1:
                        end=semi_pos+1
                        line_start=source.rfind('\n', 0, start)+1
                        prefix=source[line_start:start]
                        if prefix.strip()=='' or 'let' in prefix or 'inherit' in prefix:
                            after=source[end:]
                            nl=after.find('\n')
                            if nl!=-1:
                                between=after[:nl]
                                if between.strip()=='':
                                    end=end+nl+1
                                    start=line_start
                        edits.append((start,end,""))
    # lambda pattern edits
    # For pattern without at
    for lam in lambda_nodes:
        param=lam['param']
        if param['type']=='pattern':
            entries=param['entries']
            remaining=[e for e in entries if (e['line'],e['col'],e['name']) not in finding_keys]
            if len(remaining)==len(entries):
                continue
            # Find pattern braces
            l_off=param['l_brace'].offset if param.get('l_brace') else param.get('start_offset',0)
            r_off=source.find('}', l_off)
            if r_off==-1:
                continue
            inside_start=l_off+1
            inside_end=r_off
            new_texts=[]
            for e in remaining:
                # try to keep default if present
                # Find default src via line
                line_text=lines[e['line']-1] if e['line']-1 < len(lines) else ""
                if e['default'] is not None:
                    m=re.search(re.escape(e['name'])+r'\s*\?\s*([^,}\n]+)', line_text)
                    if m:
                        new_texts.append(f"{e['name']} ? {m.group(1).strip()}")
                    else:
                        new_texts.append(e['name'])
                else:
                    new_texts.append(e['name'])
            if len(new_texts)==0:
                if param['ellipsis']:
                    new_inside=" ... "
                else:
                    new_inside=" "
            else:
                if param['ellipsis']:
                    new_inside=" " + ", ".join(new_texts) + ", ... "
                else:
                    new_inside=" " + ", ".join(new_texts) + " "
            edits.append((inside_start, inside_end, new_inside))
        elif param['type']=='at_pattern':
            at_name=param.get('at_name')
            pat=param.get('pattern')
            at_unused=False
            if at_name:
                key=(at_name['line'],at_name['col'],at_name['name'])
                if key in finding_keys:
                    at_unused=True
            if pat and pat['type']=='pattern':
                entries=pat['entries']
                remaining=[e for e in entries if (e['line'],e['col'],e['name']) not in finding_keys]
                # Determine param region
                l_off=pat['l_brace'].offset if pat.get('l_brace') else pat.get('start_offset',0)
                r_off=source.find('}', l_off)
                if r_off==-1:
                    continue
                # param region start/end
                at_start=at_name['tok'].offset if at_name and at_name.get('tok') else l_off
                at_end=at_name['tok'].end_offset if at_name and at_name.get('tok') else l_off
                if at_name and l_off is not None:
                    if at_start < l_off:
                        param_start=at_start
                        param_end=r_off+1
                    else:
                        param_start=l_off
                        param_end=at_end
                else:
                    param_start=l_off
                    param_end=r_off+1
                if at_unused:
                    # new pattern without at_name
                    new_entries=[]
                    for e in remaining:
                        line_text=lines[e['line']-1] if e['line']-1 < len(lines) else ""
                        if e['default'] is not None:
                            m=re.search(re.escape(e['name'])+r'\s*\?\s*([^,}\n]+)', line_text)
                            if m:
                                new_entries.append(f"{e['name']} ? {m.group(1).strip()}")
                            else:
                                new_entries.append(e['name'])
                        else:
                            new_entries.append(e['name'])
                    if len(new_entries)==0:
                        if pat['ellipsis']:
                            new_pat="{ ... }"
                        else:
                            new_pat="{ }"
                    else:
                        if pat['ellipsis']:
                            new_pat="{ " + ", ".join(new_entries) + ", ... }"
                        else:
                            new_pat="{ " + ", ".join(new_entries) + " }"
                    edits.append((param_start, param_end, new_pat))
                else:
                    # at_name stays, but some entries removed
                    if len(remaining)==len(entries):
                        continue
                    new_entries=[]
                    for e in remaining:
                        line_text=lines[e['line']-1] if e['line']-1 < len(lines) else ""
                        if e['default'] is not None:
                            m=re.search(re.escape(e['name'])+r'\s*\?\s*([^,}\n]+)', line_text)
                            if m:
                                new_entries.append(f"{e['name']} ? {m.group(1).strip()}")
                            else:
                                new_entries.append(e['name'])
                        else:
                            new_entries.append(e['name'])
                    if len(new_entries)==0:
                        if pat['ellipsis']:
                            new_inside="{ ... }"
                        else:
                            new_inside="{ }"
                    else:
                        if pat['ellipsis']:
                            new_inside="{ " + ", ".join(new_entries) + ", ... }"
                        else:
                            new_inside="{ " + ", ".join(new_entries) + " }"
                    # Reconstruct full
                    at_start_off=at_name['tok'].offset if at_name and at_name.get('tok') else 0
                    if at_start_off < l_off:
                        new_full=f"{at_name['name']}@{new_inside}"
                    else:
                        new_full=f"{new_inside}@{at_name['name']}"
                    edits.append((param_start, param_end, new_full))
    # Apply edits descending
    edits_sorted=sorted(edits, key=lambda x: x[0], reverse=True)
    new_source=source
    for start,end,rep in edits_sorted:
        if start<0 or end>len(new_source) or start>end:
            continue
        new_source=new_source[:start]+rep+new_source[end:]
    pathlib.Path(path).write_text(new_source, encoding='utf-8')

