        expr=self.parse_term()
        if expr is None:
            return None
        args=[]
        while True:
            self.skip_comments()
            nxt=self.peek()
            if nxt is None:
                break
            if nxt.type in ('IN','SEMI','R_BRACE','R_BRACK','R_PAREN','COMMA','ELSE','THEN'):
                break
            if nxt.type in ('IDENT','L_BRACE','L_BRACK','L_PAREN','STRING','NUMBER','REC','IF','ASSERT','INTERP_START'):
