def render_human(files_findings, use_color):
    # files_findings is list of (file_path, source, findings_detailed)
    output=[]
    warn_text = "\x1b[33mWarning:\x1b[0m Unused declarations were found." if use_color else "Warning: Unused declarations were found."
    for file_path, source, findings in files_findings:
        if not findings:
            continue
        # Sort findings for this file by line, col
        # For human, we need to group but also header is first finding
        # We'll render one file at a time
