  -q, --quiet                          Don't print dead code report
  -e, --edit                           Remove unused code and write to source file
  -h, --hidden                         Recurse into hidden subdirectories and process hidden .*.nix files
      --help                           
  -f, --fail                           Exit with 1 if unused code has been found
  -o, --output-format <OUTPUT_FORMAT>  Output format to use [default: human-readable] [possible values: human-readable, json]
      --exclude <EXCLUDES>...          Files to exclude from analysis
  -V, --version                        Print version
"""
    print(help_text)

def parse_cli(argv):
    options={
        'no_lambda_arg':False,
        'no_lambda_pattern':False,
        'no_underscore':False,
        'warn_used_underscore':False,
        'quiet':False,
        'edit':False,
        'hidden':False,
        'fail':False,
        'output_format':'human-readable',
    }
    excludes=[]
    file_paths=[]
    # Manual parsing
    i=1
    n=len(argv)
    # State for handling -- delimiter: after encountering "--" as standalone, all remaining are file_paths
    # Also handle --exclude variadic
    while i<n:
        arg=argv[i]
        if arg=='--':
            # All remaining are file_paths
            file_paths.extend(argv[i+1:])
            break
        if arg in ('--help',):
            print_help()
            sys.exit(0)
        if arg in ('-V','--version'):
            print(VERSION)
            sys.exit(0)
        if arg in ('-l','--no-lambda-arg'):
            options['no_lambda_arg']=True
            i+=1
            continue
        if arg in ('-L','--no-lambda-pattern-names'):
            options['no_lambda_pattern']=True
            i+=1
            continue
        if arg in ('-_','--no-underscore'):
            options['no_underscore']=True
            i+=1
            continue
        if arg in ('-W','--warn-used-underscore'):
            options['warn_used_underscore']=True
            i+=1
            continue
        if arg in ('-q','--quiet'):
            options['quiet']=True
            i+=1
            continue
        if arg in ('-e','--edit'):
            options['edit']=True
            i+=1
            continue
        if arg in ('-h','--hidden'):
            options['hidden']=True
            i+=1
            continue
        if arg in ('-f','--fail'):
            options['fail']=True
            i+=1
            continue
        if arg.startswith('-o'):
            # -o json, -o=json, -ojson?
            # Handle -o=json
            if arg=='-o':
                i+=1
                if i>=n:
                    print("error: missing value for -o", file=sys.stderr)
                    sys.exit(2)
                val=argv[i]
                if val not in ('human-readable','json'):
                    print(f"error: invalid value '{val}' for '--output-format <OUTPUT_FORMAT>'\n  [possible values: human-readable, json]\n\nFor more information, try '--help'.", file=sys.stderr)
                    sys.exit(2)
                options['output_format']=val
                i+=1
                continue
            elif arg.startswith('-o='):
                val=arg[3:]
                if val not in ('human-readable','json'):
                    print(f"error: invalid value '{val}' for '--output-format <OUTPUT_FORMAT>'\n  [possible values: human-readable, json]\n\nFor more information, try '--help'.", file=sys.stderr)
                    sys.exit(2)
                options['output_format']=val
                i+=1
                continue
            elif arg.startswith('-o') and len(arg)>2:
                # -ojson ?
                val=arg[2:]
                if val.startswith('='):
                    val=val[1:]
                if val not in ('human-readable','json'):
                    print(f"error: invalid value '{val}' for '--output-format <OUTPUT_FORMAT>'\n  [possible values: human-readable, json]\n\nFor more information, try '--help'.", file=sys.stderr)
                    sys.exit(2)
                options['output_format']=val
                i+=1
                continue
        if arg in ('--output-format',):
            i+=1
            if i>=n:
                print("error: missing value for --output-format", file=sys.stderr)
                sys.exit(2)
            val=argv[i]
            if val not in ('human-readable','json'):
                print(f"error: invalid value '{val}' for '--output-format <OUTPUT_FORMAT>'\n  [possible values: human-readable, json]\n\nFor more information, try '--help'.", file=sys.stderr)
                sys.exit(2)
            options['output_format']=val
            i+=1
            continue
        if arg.startswith('--output-format='):
            val=arg.split('=',1)[1]
            if val not in ('human-readable','json'):
                print(f"error: invalid value '{val}' for '--output-format <OUTPUT_FORMAT>'\n  [possible values: human-readable, json]\n\nFor more information, try '--help'.", file=sys.stderr)
                sys.exit(2)
            options['output_format']=val
            i+=1
            continue
        if arg=='--exclude':
            i+=1
            # Collect excludes until next option or --
            while i<n:
                nxt=argv[i]
                if nxt=='--':
                    # delimiter, break and let outer loop handle --
                    break
                if nxt.startswith('-') and len(nxt)>1:
                    # Could be another option? Check if it's known option
                    # List of known options that start with -
                    known_opts=['-l','--no-lambda-arg','-L','--no-lambda-pattern-names','-_','--no-underscore','-W','--warn-used-underscore','-q','--quiet','-e','--edit','-h','--hidden','--help','-f','--fail','-o','--output-format','--exclude','-V','--version']
                    # For -o, it takes value, but we treat as option start
                    # If nxt is in known_opts or starts with -o or --output-format=, then stop collecting excludes
                    is_opt=False
                    for ko in known_opts:
                        if nxt==ko or nxt.startswith(ko+'='):
                            is_opt=True
                            break
                    # Also check -o starts with -o
                    if nxt.startswith('-o'):
                        is_opt=True
                    if nxt.startswith('--output-format'):
                        is_opt=True
                    if is_opt:
                        break
                    # If starts with - but not known, it's error? Original would error about unexpected argument. For simplicity, break as well if it looks like option (starts with -)
                    # Actually any arg starting with - should be considered option, not exclude, unless it's "--exclude" file? But file paths starting with - should be passed via --.
                    # So break
                    if nxt.startswith('-'):
                        break
                # collect as exclude
                excludes.append(nxt)
                i+=1
            continue
        if arg.startswith('--exclude='):
            # Could be --exclude=path? But original allows multiple separated by space, not sure about =.
            # We'll split
            val=arg.split('=',1)[1]
            excludes.append(val)
            i+=1
            continue
        # Handle combined short flags like -lLqf etc.
        if arg.startswith('-') and not arg.startswith('--') and len(arg)>2:
            # e.g., -lLqf, -Wq, -eq, etc. Also -_ ?
            # For each char in arg[1:], treat as separate flag, but need to handle -o which takes value
            # If arg contains 'o', then the rest after o is value? e.g., -oq json? Actually -qo json would be -q -o json combined. Our earlier test -qo json gave ? We tested -qo json and got? Let's see: -qo json with -q and -o json. In combined, -o consumes next arg as value? The original clap allows -qo json: -q and -o json? We tested earlier -qo json and got? We had -qo json gave output? We tested -qo json earlier and got exit 0 with? We tested -qo json and got? Actually we tested -qo json and got exit 0 maybe? Let's check quickly.

            # For simplicity, we will iterate chars, and when we encounter 'o', we need to handle its value: if there are remaining chars after o in same arg, they are value, else next argv is value.
            # Example: -lLqfV -o json : -l -L -q -f -V are flags, -o is separate. Combined like -lLqfVo json would be -l -L -q -f -V -o json? We tested -lLqfVo json earlier and got version printed, because -V caused exit before.
            # For -qo json: -q -o json
            # We'll implement parsing for combined.

            chars=arg[1:]
            j=0
            while j < len(chars):
                ch=chars[j]
                if ch=='l':
                    options['no_lambda_arg']=True
                elif ch=='L':
                    options['no_lambda_pattern']=True
                elif ch=='_':
                    options['no_underscore']=True
                elif ch=='W':
                    options['warn_used_underscore']=True
                elif ch=='q':
                    options['quiet']=True
                elif ch=='e':
                    options['edit']=True
                elif ch=='h':
                    options['hidden']=True
                elif ch=='f':
                    options['fail']=True
                elif ch=='V':
                    print(VERSION)
                    sys.exit(0)
                elif ch=='o':
                    # output format value
                    # If there are remaining chars after o, they are value
                    remaining=chars[j+1:]
                    if remaining:
                        val=remaining
                        if val.startswith('='):
                            val=val[1:]
                        if val not in ('human-readable','json'):
                            print(f"error: invalid value '{val}' for '--output-format <OUTPUT_FORMAT>'\n  [possible values: human-readable, json]\n\nFor more information, try '--help'.", file=sys.stderr)
                            sys.exit(2)
                        options['output_format']=val
                        break
                    else:
                        # need next arg
                        i+=1
                        if i>=n:
                            print("error: missing value for -o", file=sys.stderr)
                            sys.exit(2)
                        val=argv[i]
                        if val not in ('human-readable','json'):
                            print(f"error: invalid value '{val}' for '--output-format <OUTPUT_FORMAT>'\n  [possible values: human-readable, json]\n\nFor more information, try '--help'.", file=sys.stderr)
                            sys.exit(2)
                        options['output_format']=val
                        break
                else:
                    # unknown short flag
                    print(f"error: unexpected argument '-{ch}' found\n\n  tip: to pass '-{ch}' as a value, use '-- -{ch}'\n\nUsage: executable [OPTIONS] [FILE_PATHS]...\n\nFor more information, try '--help'.", file=sys.stderr)
                    sys.exit(2)
                j+=1
            i+=1
            continue
        if arg.startswith('-'):
            # unknown option
            print(f"error: unexpected argument '{arg}' found\n\n  tip: to pass '{arg}' as a value, use '-- {arg}'\n\nUsage: executable [OPTIONS] [FILE_PATHS]...\n\nFor more information, try '--help'.", file=sys.stderr)
            sys.exit(2)
        # otherwise file path
        file_paths.append(arg)
        i+=1

    if not file_paths:
        file_paths=['.']
    return options, excludes, file_paths

