def main():
    options, excludes, file_paths = parse_cli(sys.argv)
    files_to_process = find_nix_files(file_paths, hidden=options['hidden'], excludes=excludes)
    has_findings=False
    json_outputs=[]
    human_files=[]
    for fp in files_to_process:
        if not os.path.exists(fp):
            if options['output_format']=='json':
                json_outputs.append(json.dumps({"file":fp,"results":[{"message":"No such file or directory (os error 2)"}]}))
            else:
                if not options['quiet']:
                    print(f"Error stating file {fp}: No such file or directory (os error 2)")
            continue
        src, results, detailed, src_lines, tokens, ast = analyze_file(fp, options)
        if results:
            # For fail, check if any result is not just file not found? Our results for real findings have line/col
            # But also file not found we already handled above
            # So any results here count as findings
            has_findings=True
            if options['output_format']=='json':
                json_outputs.append(json.dumps({"file":fp,"results":results}))
            else:
                if not options['quiet']:
                    human_files.append((fp, src, detailed))
        # edit
        if options['edit'] and src is not None:
            if detailed:
                try:
                    edit_file(fp, detailed, options)
                except Exception as e:
                    import traceback
                    traceback.print_exc()
    use_color = not os.environ.get('NO_COLOR')
    if options['output_format']=='json':
        for line in json_outputs:
            print(line)
    else:
        if not options['quiet']:
            # render
            # we need to re-group? Our render expects list of (file, source, detailed)
            # For human, we need to render each file separately with warning header
            # We'll output
            warn_text = "\x1b[33mWarning:\x1b[0m Unused declarations were found." if use_color else "Warning: Unused declarations were found."
            for fp, src, detailed in human_files:
                print(warn_text)
                print(render_human_one_file(fp, src, detailed, use_color))
    if options['fail'] and has_findings:
        sys.exit(1)
    else:
        sys.exit(0)

if __name__=='__main__':
    main()
