def edit_file_simple(path,findings_detailed,options):
    source=pathlib.Path(path).read_text(encoding='utf-8')
    if not findings_detailed:
        return
    tokens,skip_lines,lines=lex(source)
    parser=Parser(tokens,source,lines,skip_lines)
    ast=parser.parse()
    let_nodes=[];lambda_nodes=[]
    def collect(node):
        if node is None:
            return
        t=node.get('type')
        if t=='let':
            let_nodes.append(node)
            for b in node['bindings']:
                if b['type']=='binding':
                    if b['expr']:
                        collect(b['expr'])
                elif b['type']=='inherit':
                    if b['from']:
                        collect(b['from'])
            collect(node['body'])
        elif t=='lambda':
            lambda_nodes.append(node)
            param=node['param']
            if param['type']=='pattern':
                for e in param['entries']:
                    if e['default']:
                        collect(e['default'])
            elif param['type']=='at_pattern':
                pat=param.get('pattern')
                if pat and pat['type']=='pattern':
                    for e in pat['entries']:
                        if e['default']:
                            collect(e['default'])
            collect(node['body'])
        elif t=='with':
            collect(node['expr']);collect(node['body'])
        elif t=='attrset':
            for b in node['bindings']:
                if b['type']=='attr_assign':
                    if b['expr']:
                        collect(b['expr'])
                elif b['type']=='inherit':
                    if b['from']:
                        collect(b['from'])
        elif t=='list':
            for e in node['elems']:
                collect(e)
        elif t=='app':
            collect(node['func'])
            for a in node['args']:
                collect(a)
        elif t=='string_interp':
            for e in node['exprs']:
                collect(e)
        elif t=='if':
            collect(node['cond']);collect(node['then']);collect(node['else'])
        elif t=='assert':
            collect(node['cond']);collect(node['body'])
    collect(ast)
    finding_keys=set((f['line'],f['col'],f['name']) for f in findings_detailed if f['type'] in ('let','let_used','lambda_pattern','lambda_pattern_used'))
    edits=[]
    for f in findings_detailed:
        if f['type']=='lambda_arg':
            tok=f['binding'].get('tok')
            if tok:
                edits.append((tok.offset,tok.end_offset,'_'+f['name'] if not f['name'].startswith('_') else f['name']))
    # let handling with simple heuristic: if all bindings unused => replace let..in with body
    for let_node in let_nodes:
        unused=[]
        for b in let_node['bindings']:
            if b['type']=='binding':
                if (b['line'],b['col'],b['name']) in finding_keys:
                    unused.append(b)
            elif b['type']=='inherit':
                remaining=[ident for ident in b['idents'] if (ident['line'],ident['col'],ident['name']) not in finding_keys]
                if len(remaining)==0:
                    unused.append(b)
                elif len(remaining)<len(b['idents']):
                    # partial - reconstruct inherit
                    start=b.get('start_offset',0)
                    semi=source.find(';',start)
                    if semi!=-1:
                        end=semi+1
                        orig=source[start:end]
                        from_text=""
                        if b['from'] is not None:
                            lpar=orig.find('(');rpar=orig.find(')',lpar)
                            if lpar!=-1 and rpar!=-1:
                                from_text=orig[lpar:rpar+1]
                        if from_text:
                            new=f"inherit {from_text} {' '.join([i['name'] for i in remaining])};"
                        else:
                            new=f"inherit {' '.join([i['name'] for i in remaining])};"
                        edits.append((start,end,new))
        if len(unused)==len(let_node['bindings']) and len(let_node['bindings'])>0:
            let_start=let_node.get('start_offset',0)
            m=re.search(r'\bin\b',source[let_start:])
            if m:
                in_end=let_start+m.end()
