                while body_start < len(source) and source[body_start] in ' \t\r\n':
                    body_start+=1
                # remove edits inside let bindings range
                edits=[e for e in edits if not (let_start <= e[0] < body_start and e[0]!=let_start)]
                edits.append((let_start,body_start,""))
        else:
            for b in unused:
                if b['type']=='binding':
                    tok=b.get('tok')
                    if not tok:
                        continue
                    start=tok.offset
                    semi=source.find(';',start)
                    if semi==-1:
                        continue
                    end=semi+1
                    j=end
                    while j < len(source) and source[j] in ' \t':
                        j+=1
                    line_no=b['line']
                    line_start=source.rfind('\n',0,start)+1
                    prefix=source[line_start:start]
                    if prefix.strip()=='' or prefix.strip()=='let':
                        after=source[end:]
                        nl=after.find('\n')
                        if nl!=-1:
                            between=after[:nl]
                            if between.strip()=='':
                                end=end+nl+1
                                start=line_start
                    else:
                        end=j
                    edits.append((start,end,""))
                elif b['type']=='inherit':
                    start=b.get('start_offset',0)
                    semi=source.find(';',start)
                    if semi==-1:
                        continue
                    end=semi+1
                    line_start=source.rfind('\n',0,start)+1
                    prefix=source[line_start:start]
                    if prefix.strip()=='' or 'let' in prefix or 'inherit' in prefix:
                        after=source[end:]
                        nl=after.find('\n')
                        if nl!=-1 and after[:nl].strip()=='':
                            end=end+nl+1
                            start=line_start
                    edits.append((start,end,""))
