    for lam in lambda_nodes:
        param=lam['param']
        if param['type']=='pattern':
            entries=param['entries']
            remaining=[e for e in entries if (e['line'],e['col'],e['name']) not in finding_keys]
            if len(remaining)==len(entries):
                continue
            l_off=param['l_brace'].offset if param.get('l_brace') else param.get('start_offset',0)
            r_off=source.find('}',l_off)
            if r_off==-1:
                continue
            inside_start=l_off+1;inside_end=r_off
            new_texts=[]
            for e in remaining:
                # keep default if any: try to extract from line
                line_text=lines[e['line']-1] if e['line']-1 < len(lines) else ""
                if e['default'] is not None:
                    mm=re.search(re.escape(e['name'])+r'\s*\?\s*([^,}\n]+)',line_text)
                    if mm:
                        new_texts.append(f"{e['name']} ? {mm.group(1).strip()}")
                    else:
                        new_texts.append(e['name'])
                else:
                    new_texts.append(e['name'])
            if not new_texts:
                new_inside=" ... " if param['ellipsis'] else " "
            else:
                if param['ellipsis']:
                    new_inside=" " + ", ".join(new_texts) + ", ... "
                else:
                    new_inside=" " + ", ".join(new_texts) + " "
            edits.append((inside_start,inside_end,new_inside))
        elif param['type']=='at_pattern':
            at_name=param.get('at_name')
            pat=param.get('pattern')
            at_unused=False
            if at_name and (at_name['line'],at_name['col'],at_name['name']) in finding_keys:
                at_unused=True
            if pat and pat['type']=='pattern':
                entries=pat['entries']
                remaining=[e for e in entries if (e['line'],e['col'],e['name']) not in finding_keys]
                l_off=pat['l_brace'].offset if pat.get('l_brace') else pat.get('start_offset',0)
                r_off=source.find('}',l_off)
                if r_off==-1:
                    continue
                at_start=at_name['tok'].offset if at_name and at_name.get('tok') else l_off
                at_end=at_name['tok'].end_offset if at_name and at_name.get('tok') else l_off
                if at_start < l_off:
                    p_start=at_start; p_end=r_off+1
                else:
                    p_start=l_off; p_end=at_end
                if at_unused:
                    new_entries=[]
                    for e in remaining:
                        lt=lines[e['line']-1] if e['line']-1 < len(lines) else ""
                        if e['default'] is not None:
                            mm=re.search(re.escape(e['name'])+r'\s*\?\s*([^,}\n]+)',lt)
                            if mm:
                                new_entries.append(f"{e['name']} ? {mm.group(1).strip()}")
                            else:
                                new_entries.append(e['name'])
                        else:
                            new_entries.append(e['name'])
                    if not new_entries:
                        new_pat="{ ... }" if pat['ellipsis'] else "{ }"
                    else:
                        if pat['ellipsis']:
                            new_pat="{ " + ", ".join(new_entries) + ", ... }"
                        else:
                            new_pat="{ " + ", ".join(new_entries) + " }"
                    edits.append((p_start,p_end,new_pat))
                else:
                    if len(remaining)==len(entries):
                        continue
                    new_entries=[]
                    for e in remaining:
                        lt=lines[e['line']-1] if e['line']-1 < len(lines) else ""
                        if e['default'] is not None:
                            mm=re.search(re.escape(e['name'])+r'\s*\?\s*([^,}\n]+)',lt)
                            if mm:
                                new_entries.append(f"{e['name']} ? {mm.group(1).strip()}")
                            else:
                                new_entries.append(e['name'])
                        else:
                            new_entries.append(e['name'])
                    if not new_entries:
                        new_inside="{ ... }" if pat['ellipsis'] else "{ }"
                    else:
                        if pat['ellipsis']:
                            new_inside="{ " + ", ".join(new_entries) + ", ... }"
                        else:
                            new_inside="{ " + ", ".join(new_entries) + " }"
                    if at_start < l_off:
                        new_full=f"{at_name['name']}@{new_inside}"
                    else:
                        new_full=f"{new_inside}@{at_name['name']}"
                    edits.append((p_start,p_end,new_full))
    edits_sorted=sorted(edits,key=lambda x:x[0],reverse=True)
    new_src=source
    for s,e,r in edits_sorted:
        if s<0 or e>len(new_src) or s>e:
            continue
        new_src=new_src[:s]+r+new_src[e:]
    pathlib.Path(path).write_text(new_src,encoding='utf-8')

def main():
    options,excludes,file_paths=parse_cli(sys.argv)
    files=find_nix_files(file_paths,hidden=options['hidden'],excludes=excludes)
    has=False
    json_out=[]
    human_files=[]
    for fp in files:
        if not os.path.exists(fp):
            if options['output_format']=='json':
                json_out.append(json.dumps({"file":fp,"results":[{"message":"No such file or directory (os error 2)"}]}))
            else:
                if not options['quiet']:
                    print(f"Error stating file {fp}: No such file or directory (os error 2)")
            continue
        src,results,detailed,src_lines,tokens,ast,_=analyze_file(fp,options)
        if results:
            has=True
            if options['output_format']=='json':
                json_out.append(json.dumps({"file":fp,"results":results}))
            else:
                if not options['quiet']:
                    human_files.append((fp,src,detailed))
        if options['edit'] and src is not None and detailed:
            try:
                edit_file_simple(fp,detailed,options)
            except Exception as e:
                import traceback;traceback.print_exc()
    use_color=not os.environ.get('NO_COLOR')
    if options['output_format']=='json':
        for l in json_out:
            print(l)
    else:
        if not options['quiet']:
            warn="\x1b[33mWarning:\x1b[0m Unused declarations were found." if use_color else "Warning: Unused declarations were found."
            for fp,src,detailed in human_files:
                print(warn)
                print(render_human_one_file(fp,src,detailed,use_color))
    if options['fail'] and has:
        sys.exit(1)
    else:
        sys.exit(0)

if __name__=='__main__':
    main()
