        nodes.append(first)
        while True:
            self.skip_comments()
            nxt=self.peek()
            if nxt is None:
                break
            if nxt.type in ('IN','SEMI','R_BRACE','R_BRACK','R_PAREN','COMMA','ELSE','THEN'):
                break
            if nxt.type=='OP':
                self.consume('OP')
                term=self.parse_term()
                if term:
                    nodes.append(term)
                continue
            if nxt.type in ('IDENT','L_BRACE','L_BRACK','L_PAREN','STRING','NUMBER','REC','IF','ASSERT','INTERP_START'):
                term=self.parse_term()
                if term:
                    nodes.append(term)
                else:
                    break
            else:
                break
