            return nodes[0]
        return {'type':'combine','exprs':nodes}
    def parse_term(self):
        self.skip_comments()
        t=self.peek()
        if t is None:
            return None
        if t.type=='L_BRACE':
            return self.parse_attrset()
        if t.type=='L_BRACK':
            return self.parse_list()
        if t.type=='L_PAREN':
            self.consume('L_PAREN')
            inner=self.parse_expr()
            self.skip_comments()
            self.consume('R_PAREN')
            return inner
        if t.type=='IDENT':
            ident=self.consume('IDENT')
            while True:
                self.skip_comments()
                nxt=self.peek()
                if nxt and nxt.type=='DOT':
                    self.consume('DOT')
                    nn=self.peek()
                    if nn and nn.type=='IDENT':
                        self.consume('IDENT')
                    elif nn and nn.type=='STRING':
                        self.consume('STRING')
                    else:
                        break
                else:
                    break
            return {'type':'var','name':ident.text,'line':ident.line,'col':ident.col,'end_col':ident.end_col,'tok':ident}
        if t.type=='INTERP_START':
            self.consume('INTERP_START')
            expr=self.parse_expr()
            self.skip_comments()
            self.consume('INTERP_END')
            return expr
        if t.type=='STRING':
            return self.parse_string_with_interps()
        if t.type=='NUMBER':
            self.consume('NUMBER')
            return {'type':'literal'}
        if t.type=='REC':
            self.consume('REC')
            self.skip_comments()
            if self.peek() and self.peek().type=='L_BRACE':
                return self.parse_attrset(rec=True)
            return {'type':'rec'}
        if t.type=='IF':
            self.consume('IF')
            cond=self.parse_expr()
            self.skip_comments()
            self.consume('THEN')
            then_e=self.parse_expr()
            self.skip_comments()
            self.consume('ELSE')
            else_e=self.parse_expr()
            return {'type':'if','cond':cond,'then':then_e,'else':else_e}
        if t.type=='ASSERT':
            self.consume('ASSERT')
            cond=self.parse_expr()
            self.skip_comments()
            self.consume('SEMI')
            body=self.parse_expr()
            return {'type':'assert','cond':cond,'body':body}
        self.pos+=1
        return None
    def parse_string_with_interps(self):
        exprs=[]
        while True:
            self.skip_comments()
            t=self.peek()
            if t is None:
                break
            if t.type=='STRING':
                self.consume('STRING')
                continue
            if t.type=='INTERP_START':
                self.consume('INTERP_START')
                e=self.parse_expr()
                if e:
                    exprs.append(e)
                self.skip_comments()
                self.consume('INTERP_END')
                continue
            break
        if exprs:
            return {'type':'string_interp','exprs':exprs}
        return {'type':'string'}
    def parse_attrset(self,rec=False):
        self.skip_comments()
        start=self.consume('L_BRACE')
        if start is None:
            return None
        bindings=[]
        while True:
            self.skip_comments()
            t=self.peek()
            if t is None:
                break
            if t.type=='R_BRACE':
                self.consume('R_BRACE')
                break
            if t.type=='INHERIT':
                inh=self.parse_inherit()
                if inh:
                    bindings.append(inh)
                continue
            attrpath=self.parse_attrpath()
            if attrpath is None:
                self.pos+=1
                continue
            self.skip_comments()
            eq=self.consume('EQ')
            if eq is None:
                while self.peek() and self.peek().type not in ('SEMI','R_BRACE'):
                    self.pos+=1
                if self.peek() and self.peek().type=='SEMI':
                    self.consume('SEMI')
                continue
            self.skip_comments()
            expr=self.parse_expr()
            self.skip_comments()
            self.consume('SEMI')
            bindings.append({'type':'attr_assign','path':attrpath,'expr':expr})
        return {'type':'attrset','rec':rec,'bindings':bindings,'line':start.line if start else 0,'start_offset':start.offset if start else 0}
    def parse_attrpath(self):
        self.skip_comments()
        names=[];toks=[];interps=[]
        while True:
            self.skip_comments()
            t=self.peek()
            if t is None:
                break
            if t.type=='IDENT':
                tok=self.consume('IDENT')
                names.append(tok.text);toks.append(tok)
            elif t.type=='STRING':
                self.consume('STRING')
                names.append('<string>');toks.append(t)
            elif t.type=='INTERP_START':
                self.consume('INTERP_START')
                e=self.parse_expr()
                self.consume('INTERP_END')
                names.append('<interp>')
                if e:
                    interps.append(e)
            else:
                break
            self.skip_comments()
            nxt=self.peek()
            if nxt and nxt.type=='DOT':
                self.consume('DOT')
                continue
