        if names:
            return {'names':names,'toks':toks,'interps':interps}
        return None
    def parse_inherit(self):
        self.skip_comments()
        inherit_tok=self.consume('INHERIT')
        if inherit_tok is None:
            return None
        self.skip_comments()
        from_expr=None
        if self.peek() and self.peek().type=='L_PAREN':
            self.consume('L_PAREN')
            from_expr=self.parse_expr()
            self.skip_comments()
            self.consume('R_PAREN')
        idents=[]
        while True:
            self.skip_comments()
            tok=self.peek()
            if tok and tok.type=='IDENT':
                id_tok=self.consume('IDENT')
                is_skipped=(id_tok.line-1) in self.skip_lines
                idents.append({'name':id_tok.text,'line':id_tok.line,'col':id_tok.col,'end_col':id_tok.end_col,'skip':is_skipped,'tok':id_tok})
            else:
                break
        self.skip_comments()
        self.consume('SEMI')
        return {'type':'inherit','from':from_expr,'idents':idents,'line':inherit_tok.line,'start_offset':inherit_tok.offset}
    def parse_let(self):
        let_tok=self.consume('LET')
        bindings=[]
        while True:
            self.skip_comments()
            tok=self.peek()
            if tok is None:
                break
            if tok.type=='IN':
                self.consume('IN')
                break
            if tok.type=='INHERIT':
                inh=self.parse_inherit()
                if inh:
                    bindings.append(inh)
                continue
            if tok and tok.type not in ('IDENT','STRING'):
                self.pos+=1
                continue
            attrpath=self.parse_attrpath()
            if attrpath is None:
                self.pos+=1
                continue
            self.skip_comments()
            eq=self.consume('EQ')
            if eq is None:
                while self.peek() and self.peek().type not in ('SEMI','IN'):
                    self.pos+=1
                if self.peek() and self.peek().type=='SEMI':
                    self.consume('SEMI')
                continue
            self.skip_comments()
            expr=self.parse_expr()
            self.skip_comments()
            semi=self.consume('SEMI')
            first_name=attrpath['names'][0] if attrpath['names'] else None
            first_tok=attrpath['toks'][0] if attrpath['toks'] else None
            if first_name and first_name not in ('<string>','<interp>'):
                line=first_tok.line if first_tok else 0
                col=first_tok.col if first_tok else 0
                end_col=first_tok.end_col if first_tok else 0
                is_skipped=(line-1) in self.skip_lines
                bindings.append({'type':'binding','name':first_name,'expr':expr,'line':line,'col':col,'end_col':end_col,'skip':is_skipped,'attrpath':attrpath,'tok':first_tok,'semi':semi})
        body=self.parse_expr()
        return {'type':'let','bindings':bindings,'body':body,'line':let_tok.line if let_tok else 0,'start_offset':let_tok.offset if let_tok else 0}
    def parse_with(self):
        with_tok=self.consume('WITH')
        expr=self.parse_expr()
        self.skip_comments()
        self.consume('SEMI')
        body=self.parse_expr()
        return {'type':'with','expr':expr,'body':body,'line':with_tok.line if with_tok else 0}
    def try_parse_lambda_param(self):
        saved=self.pos
        self.skip_comments()
        tok=self.peek()
        if tok is None:
            return None
        if tok.type=='IDENT':
            ident_tok=self.consume('IDENT')
            self.skip_comments()
            nxt=self.peek()
            if nxt and nxt.type=='AT':
                self.consume('AT')
                self.skip_comments()
                nxt2=self.peek()
                if nxt2 and nxt2.type=='L_BRACE':
                    pat=self.parse_pattern()
                    if pat:
                        return {'type':'at_pattern','at_name':{'name':ident_tok.text,'line':ident_tok.line,'col':ident_tok.col,'end_col':ident_tok.end_col,'skip':(ident_tok.line-1) in self.skip_lines,'tok':ident_tok},'pattern':pat}
                elif nxt2 and nxt2.type=='IDENT':
                    ident2=self.consume('IDENT')
                    pat={'type':'simple','name':ident2.text,'line':ident2.line,'col':ident2.col,'end_col':ident2.end_col,'skip':(ident2.line-1) in self.skip_lines,'tok':ident2}
                    return {'type':'at_pattern','at_name':{'name':ident_tok.text,'line':ident_tok.line,'col':ident_tok.col,'end_col':ident_tok.end_col,'skip':(ident_tok.line-1) in self.skip_lines,'tok':ident_tok},'pattern':pat}
                else:
                    self.pos=saved
                    return None
            else:
                return {'type':'simple','name':ident_tok.text,'line':ident_tok.line,'col':ident_tok.col,'end_col':ident_tok.end_col,'skip':(ident_tok.line-1) in self.skip_lines,'tok':ident_tok}
        if tok.type=='L_BRACE':
            pat=self.parse_pattern()
            if pat is None:
                self.pos=saved
                return None
            self.skip_comments()
            nxt=self.peek()
            if nxt and nxt.type=='AT':
                self.consume('AT')
                self.skip_comments()
                ident_tok=self.consume('IDENT')
                if ident_tok is None:
                    self.pos=saved
                    return None
                return {'type':'at_pattern','pattern':pat,'at_name':{'name':ident_tok.text,'line':ident_tok.line,'col':ident_tok.col,'end_col':ident_tok.end_col,'skip':(ident_tok.line-1) in self.skip_lines,'tok':ident_tok}}
            else:
                return pat
        return None
    def parse_pattern(self):
        self.skip_comments()
        l_brace=self.consume('L_BRACE')
        if l_brace is None:
            return None
        entries=[];has_ellipsis=False;ellipsis_tok=None
        saved_pos=self.pos
        while True:
            self.skip_comments()
            tok=self.peek()
            if tok is None:
                break
            if tok.type=='R_BRACE':
                self.consume('R_BRACE')
                break
            if tok.type=='ELLIPSIS':
                has_ellipsis=True
                ellipsis_tok=self.consume('ELLIPSIS')
                self.skip_comments()
                if self.peek() and self.peek().type=='COMMA':
                    self.consume('COMMA')
                continue
            if tok.type=='IDENT':
                ident_tok=self.consume('IDENT')
                self.skip_comments()
                nxt=self.peek()
                if nxt and nxt.type=='EQ':
                    self.pos=saved_pos
                    return None
                default_expr=None
                if self.peek() and self.peek().type=='QUESTION':
                    self.consume('QUESTION')
                    self.skip_comments()
                    default_expr=self.parse_expr()
                self.skip_comments()
                if self.peek() and self.peek().type=='COMMA':
                    self.consume('COMMA')
                is_skipped=(ident_tok.line-1) in self.skip_lines
                entries.append({'name':ident_tok.text,'line':ident_tok.line,'col':ident_tok.col,'end_col':ident_tok.end_col,'default':default_expr,'skip':is_skipped,'tok':ident_tok})
                continue
            if tok.type=='COMMA':
                self.consume('COMMA')
                continue
            if tok.type in ('INHERIT','EQ','SEMI'):
                self.pos=saved_pos
                return None
            self.pos+=1
        return {'type':'pattern','entries':entries,'ellipsis':has_ellipsis,'ellipsis_tok':ellipsis_tok,'line':l_brace.line,'start_offset':l_brace.offset,'l_brace':l_brace}
    def parse_list(self):
        self.consume('L_BRACK')
        elems=[]
        while True:
            self.skip_comments()
            tok=self.peek()
            if tok is None or tok.type=='R_BRACK':
                self.consume('R_BRACK')
                break
            expr=self.parse_expr()
            if expr:
                elems.append(expr)
        return {'type':'list','elems':elems}

def get_attrset_keys(node):
    if node is None or node.get('type')!='attrset':
        return None
    keys=[]
    for b in node['bindings']:
        if b['type']=='attr_assign':
            path=b.get('path')
            if isinstance(path,dict):
                names=path.get('names',[])
                if names:
                    first=names[0]
                    if first not in ('<string>','<interp>'):
                        keys.append(first)
        elif b['type']=='inherit':
            for ident in b['idents']:
                keys.append(ident['name'])
    return keys

class Analyzer:
    def __init__(self,source,lines,skip_lines,options):
        self.source=source;self.lines=lines;self.skip_lines=skip_lines;self.options=options;self.findings=[]
    def analyze(self,node,scope_stack=None,with_shadows=None):
        if scope_stack is None:
            scope_stack=[]
        if with_shadows is None:
            with_shadows=[]
        if node is None:
            return set()
        t=node.get('type')
        if t=='var':
            name=node['name']
            return {name}
        if t=='let':
            let_bindings=[];name_to_indices={}
            for b in node['bindings']:
                if b['type']=='binding':
                    idx=len(let_bindings)
                    let_bindings.append({'name':b['name'],'expr':b['expr'],'line':b['line'],'col':b['col'],'end_col':b['end_col'],'skip':b['skip'],'tok':b['tok'],'type':'let'})
                    name_to_indices.setdefault(b['name'],[]).append(idx)
                elif b['type']=='inherit':
                    for ident in b['idents']:
                        idx=len(let_bindings)
                        let_bindings.append({'name':ident['name'],'line':ident['line'],'col':ident['col'],'end_col':ident['end_col'],'skip':ident['skip'],'tok':ident['tok'],'type':'let_inherit','from':b['from']})
                        name_to_indices.setdefault(ident['name'],[]).append(idx)
            body_used=self.analyze(node['body'],scope_stack+[let_bindings],with_shadows[:])
            binding_refs=[]
            for b in let_bindings:
                if b['type']=='let' and b.get('expr'):
                    refs=self.analyze(b['expr'],scope_stack+[let_bindings],with_shadows[:])
                    binding_refs.append(refs)
                elif b['type']=='let_inherit':
                    refs=set()
                    if b['from']:
                        refs.update(self.analyze(b['from'],scope_stack+[let_bindings],with_shadows[:]))
                    binding_refs.append(refs)
                else:
                    binding_refs.append(set())
            deps=[set() for _ in let_bindings]
            for i,refs in enumerate(binding_refs):
                for var_name in refs:
                    if var_name in name_to_indices:
                        for j in name_to_indices[var_name]:
                            if j!=i:
                                deps[i].add(j)
            used_indices=set()
            for var_name in body_used:
                if var_name in name_to_indices:
                    for idx in name_to_indices[var_name]:
                        used_indices.add(idx)
            changed=True
            while changed:
                changed=False
                new=set()
                for idx in used_indices:
                    for dep in deps[idx]:
                        if dep not in used_indices:
                            new.add(dep)
                if new:
                    used_indices.update(new);changed=True
            for idx,b in enumerate(let_bindings):
                if idx in used_indices:
                    if b['name'].startswith('_') and self.options.get('warn_used_underscore'):
                        if b['skip']:
                            continue
                        if b['name'].startswith('_') and self.options.get('no_underscore'):
                            continue
                        self.findings.append({'name':b['name'],'line':b['line'],'col':b['col'],'end_col':b['end_col'],'type':'let_used','message':f"Used let binding: {b['name']}",'binding':b})
                    continue
                if b['skip']:
                    continue
                name=b['name']
                if name.startswith('_') and self.options.get('no_underscore'):
                    continue
                self.findings.append({'name':name,'line':b['line'],'col':b['col'],'end_col':b['end_col'],'type':'let','message':f"Unused let binding: {name}",'binding':b})
            outer=set()
            outer.update([n for n in body_used if n not in name_to_indices])
            for idx in used_indices:
                for var_name in binding_refs[idx]:
                    if var_name not in name_to_indices:
                        outer.add(var_name)
            return outer
        if t=='with':
            expr_used=self.analyze(node['expr'],scope_stack,with_shadows)
            body_used=self.analyze(node['body'],scope_stack,with_shadows)
            outer=set();outer.update(expr_used);outer.update(body_used);return outer
        if t=='lambda':
            param=node['param'];param_bindings=[]
            if param['type']=='simple':
                param_bindings.append({'name':param['name'],'line':param['line'],'col':param['col'],'end_col':param['end_col'],'skip':param['skip'],'type':'lambda_arg','default':None,'tok':param.get('tok')})
            elif param['type']=='pattern':
                for e in param['entries']:
                    param_bindings.append({'name':e['name'],'line':e['line'],'col':e['col'],'end_col':e['end_col'],'skip':e['skip'],'type':'lambda_pattern','default':e['default'],'tok':e.get('tok')})
            elif param['type']=='at_pattern':
                at_name=param.get('at_name')
                if at_name:
                    param_bindings.append({'name':at_name['name'],'line':at_name['line'],'col':at_name['col'],'end_col':at_name['end_col'],'skip':at_name['skip'],'type':'lambda_pattern','default':None,'tok':at_name.get('tok'),'is_at':True})
                pat=param.get('pattern')
                if pat:
                    if pat['type']=='simple':
                        param_bindings.append({'name':pat['name'],'line':pat['line'],'col':pat['col'],'end_col':pat['end_col'],'skip':pat['skip'],'type':'lambda_pattern','default':None,'tok':pat.get('tok')})
                    elif pat['type']=='pattern':
                        for e in pat['entries']:
                            param_bindings.append({'name':e['name'],'line':e['line'],'col':e['col'],'end_col':e['end_col'],'skip':e['skip'],'type':'lambda_pattern','default':e['default'],'tok':e.get('tok')})
            body_used=self.analyze(node['body'],scope_stack+[param_bindings],with_shadows[:])
            param_refs=[]
            for b in param_bindings:
                if b['default']:
                    refs=self.analyze(b['default'],scope_stack+[param_bindings],with_shadows[:])
                    param_refs.append(refs)
                else:
                    param_refs.append(set())
            name_to_indices={}
            for idx,b in enumerate(param_bindings):
                name_to_indices.setdefault(b['name'],[]).append(idx)
            deps=[set() for _ in param_bindings]
            for i,refs in enumerate(param_refs):
                for var_name in refs:
                    if var_name in name_to_indices:
                        for j in name_to_indices[var_name]:
                            if j!=i:
                                deps[i].add(j)
            used_indices=set()
            for var_name in body_used:
                if var_name in name_to_indices:
                    for idx in name_to_indices[var_name]:
                        used_indices.add(idx)
            changed=True
            while changed:
                changed=False
                new=set()
                for idx in used_indices:
                    for dep in deps[idx]:
                        if dep not in used_indices:
                            new.add(dep)
                if new:
                    used_indices.update(new);changed=True
            for idx,b in enumerate(param_bindings):
                if idx in used_indices:
                    if b['name'].startswith('_') and self.options.get('warn_used_underscore'):
                        if b['skip']:
                            continue
                        if b['type']=='lambda_arg' and b['name'].startswith('_'):
                            continue
                        if b['name'].startswith('_') and self.options.get('no_underscore'):
                            continue
                        if b['type']=='lambda_pattern':
                            self.findings.append({'name':b['name'],'line':b['line'],'col':b['col'],'end_col':b['end_col'],'type':'lambda_pattern_used','message':f"Used lambda pattern: {b['name']}",'binding':b})
                    continue
                if b['skip']:
                    continue
                name=b['name']
                if b['type']=='lambda_arg':
                    if self.options.get('no_lambda_arg'):
                        continue
                    if name.startswith('_'):
                        continue
                    msg=f"Unused lambda argument: {name}"
                else:
                    if self.options.get('no_lambda_pattern'):
                        continue
                    if name.startswith('_') and self.options.get('no_underscore'):
                        continue
                    msg=f"Unused lambda pattern: {name}"
                self.findings.append({'name':name,'line':b['line'],'col':b['col'],'end_col':b['end_col'],'type':b['type'],'message':msg,'binding':b})
            outer=set()
            outer.update([n for n in body_used if n not in name_to_indices])
            for idx in used_indices:
                for var_name in param_refs[idx]:
                    if var_name not in name_to_indices:
                        outer.add(var_name)
            return outer
        if t=='attrset':
            outer=set()
            for b in node['bindings']:
                if b['type']=='inherit':
                    if b['from']:
                        outer.update(self.analyze(b['from'],scope_stack,with_shadows))
                    if b['from'] is None:
                        for ident in b['idents']:
                            outer.add(ident['name'])
                elif b['type']=='attr_assign':
                    if b['expr']:
                        outer.update(self.analyze(b['expr'],scope_stack,with_shadows))
                    path=b.get('path')
                    if isinstance(path,dict) and 'interps' in path:
                        for inter in path['interps']:
                            outer.update(self.analyze(inter,scope_stack,with_shadows))
            return outer
        if t=='list':
            s=set()
            for e in node['elems']:
                s.update(self.analyze(e,scope_stack,with_shadows))
            return s
        if t=='app':
            s=set()
            s.update(self.analyze(node['func'],scope_stack,with_shadows))
            for a in node['args']:
                s.update(self.analyze(a,scope_stack,with_shadows))
            return s
        if t=='string_interp':
            s=set()
            for e in node['exprs']:
                s.update(self.analyze(e,scope_stack,with_shadows))
            return s
        if t=='combine':
            s=set()
            for e in node['exprs']:
                s.update(self.analyze(e,scope_stack,with_shadows))
            return s
        if t=='if':
            s=set()
            s.update(self.analyze(node['cond'],scope_stack,with_shadows))
            s.update(self.analyze(node['then'],scope_stack,with_shadows))
            s.update(self.analyze(node['else'],scope_stack,with_shadows))
            return s
        if t=='assert':
            s=set()
            s.update(self.analyze(node['cond'],scope_stack,with_shadows))
            s.update(self.analyze(node['body'],scope_stack,with_shadows))
            return s
        return set()

def analyze_source(source,options):
    tokens,skip_lines,lines=lex(source)
    parser=Parser(tokens,source,lines,skip_lines)
    ast=parser.parse()
    analyzer=Analyzer(source,lines,skip_lines,options)
    try:
        analyzer.analyze(ast)
    except Exception:
        import traceback;traceback.print_exc()
    findings_sorted=sorted(analyzer.findings,key=lambda x:(x['line'],x['col']))
    return findings_sorted,source,lines,skip_lines,tokens,ast

def analyze_file(path,options):
    try:
        source=pathlib.Path(path).read_text(encoding='utf-8')
    except FileNotFoundError:
        return None,[{"message":"No such file or directory (os error 2)"}],[],"",[],[],None
    findings,src,src_lines,skip_lines,tokens,ast=analyze_source(source,options)
    results=[]
    for f in findings:
        results.append({'column':f['col'],'endColumn':f['end_col'],'line':f['line'],'message':f['message']})
    return src,results,findings,src_lines,tokens,ast,None

def find_nix_files(paths,hidden=False,excludes=None):
    if excludes is None:
        excludes=[]
    excl_abs=[]
    for p in excludes:
        try:
            if os.path.isabs(p):
                excl_abs.append(os.path.normpath(p))
            else:
                excl_abs.append(os.path.normpath(os.path.join(os.getcwd(),p)))
        except:
            excl_abs.append(p)
    def is_excluded(fp):
        fp_abs=os.path.normpath(os.path.abspath(fp))
        for ex in excl_abs:
            if fp_abs==ex:
                return True
            if fp_abs.startswith(ex+os.sep):
                return True
        return False
    collected=[]
    for p in paths:
        if not os.path.exists(p):
            collected.append(p);continue
        if os.path.isfile(p):
            collected.append(p)
        elif os.path.isdir(p):
            for root,dirs,files in os.walk(p,topdown=True):
                if not hidden:
                    dirs[:]=[d for d in dirs if not d.startswith('.')]
                dirs.sort();files.sort()
                for f in files:
                    if not hidden and f.startswith('.'):
                        continue
                    if not f.endswith('.nix'):
                        continue
                    full=os.path.join(root,f)
                    if is_excluded(full):
                        continue
                    collected.append(full)
        else:
            collected.append(p)
    return collected

def render_human_one_file(file_path,source,findings,use_color):
    if not findings:
        return ""
    sorted_findings=sorted(findings,key=lambda x:(x['line'],x['col']))
    src_lines=source.splitlines()
    total_lines=len(src_lines) if src_lines else 1
    width=len(str(total_lines))+1
    first=sorted_findings[0]
    indent=" "*(width+1)
    if use_color:
        header=f"{indent}\x1b[38;5;246m╭\x1b[0m\x1b[38;5;246m─\x1b[0m\x1b[38;5;246m[\x1b[0m{file_path}:{first['line']}:{first['col']}\x1b[38;5;246m]\x1b[0m"
    else:
        header=f"{indent}╭─[{file_path}:{first['line']}:{first['col']}]"
    by_line=defaultdict(list)
    for f in sorted_findings:
        by_line[f['line']].append(f)
    out=[];out.append(header)
    for line_no in sorted(by_line.keys()):
        src_text=src_lines[line_no-1] if line_no-1 < len(src_lines) else ""
        if use_color:
            line_findings_asc=sorted(by_line[line_no],key=lambda x:x['col'])
            colored_src="";last=0
            for f in line_findings_asc:
                start=f['col']-1;end=f['end_col']-1
                if start<0:
                    start=0
                if end>len(src_text):
                    end=len(src_text)
                if start>len(src_text):
                    continue
                if start>last:
                    colored_src+=src_text[last:start]
                ident=src_text[start:end]
                if 'let' in f['type']:
                    cc=31
                elif 'lambda_pattern' in f['type']:
                    cc=35
                else:
                    cc=36
                colored_src+=f"\x1b[{cc}m{ident}\x1b[0m"
                last=end
            if last < len(src_text):
                colored_src+=src_text[last:]
            line_no_str=f"\x1b[38;5;246m{line_no:>{width}} │\x1b[0m"
            out.append(f"{line_no_str}{colored_src}")
        else:
            out.append(f"{line_no:>{width}} │{src_text}")
        line_findings=by_line[line_no]
        for f in line_findings:
            f['_middle']=(f['col']+f['end_col'])//2
            f['_end']=f['end_col']
        line_sorted=sorted(line_findings,key=lambda x:x['_middle'],reverse=True)
        dashes=[]
        for idx,f in enumerate(line_sorted):
            if idx==0:
                d=f['_end']-f['_middle']
                if d<=0:
                    d=1
                dashes.append(d)
            else:
                prev=line_sorted[idx-1]['_middle']
                cur=f['_middle']
                d=(prev - cur) + dashes[idx-1]
                dashes.append(d)
        for idx,f in enumerate(line_sorted):
            middle=f['_middle'];dash=dashes[idx];remaining=line_sorted[idx+1:];buf_len=middle+dash;buf=[' ']*buf_len
            for rem in remaining:
                m=rem['_middle']
                if 0 <= m-1 < len(buf):
                    buf[m-1]='│'
            if 0 <= middle-1 < len(buf):
                buf[middle-1]='╰'
            for k in range(dash):
                pos=middle-1+1+k
                if 0 <= pos < len(buf):
                    buf[pos]='─'
            after=''.join(buf)
            if use_color:
                colored=[]
                for pos,ch in enumerate(buf):
                    if ch==' ':
                        colored.append(' ')
                    elif ch=='│':
                        match=None
                        for rem in remaining:
                            if rem['_middle']-1==pos:
                                match=rem;break
                        if match:
                            cc=31 if 'let' in match['type'] else (35 if 'lambda_pattern' in match['type'] else 36)
                            colored.append(f"\x1b[{cc}m│\x1b[0m")
                        else:
                            colored.append('│')
                    elif ch=='╰':
                        cc=31 if 'let' in f['type'] else (35 if 'lambda_pattern' in f['type'] else 36)
                        colored.append(f"\x1b[{cc}m╰\x1b[0m")
                    elif ch=='─':
                        cc=31 if 'let' in f['type'] else (35 if 'lambda_pattern' in f['type'] else 36)
                        colored.append(f"\x1b[{cc}m─\x1b[0m")
                    else:
                        colored.append(ch)
                after_c=''.join(colored)
                ptr_indent=f"{' '*(width+1)}\x1b[38;5;240m│\x1b[0m"
                out.append(f"{ptr_indent}{after_c} {f['message']}")
            else:
                out.append(f"{' '*(width+1)}│{after} {f['message']}")
    return "\n".join(out)

def print_help():
    print("Find dead code in .nix files\n\nUsage: executable [OPTIONS] [FILE_PATHS]...\n\nArguments:\n  [FILE_PATHS]...  .nix files, or directories with .nix files inside [default: .]\n\nOptions:\n  -l, --no-lambda-arg                  Don't check lambda parameter arguments\n  -L, --no-lambda-pattern-names        Don't check lambda attrset pattern names (don't break nixpkgs callPackage)\n  -_, --no-underscore                  Don't check any bindings that start with a _\n                                       (Lambda arguments starting with _ are not checked anyway.)\n  -W, --warn-used-underscore           Warn if bindings are referenced that start with '_'\n  -q, --quiet                          Don't print dead code report\n  -e, --edit                           Remove unused code and write to source file\n  -h, --hidden                         Recurse into hidden subdirectories and process hidden .*.nix files\n      --help                           \n  -f, --fail                           Exit with 1 if unused code has been found\n  -o, --output-format <OUTPUT_FORMAT>  Output format to use [default: human-readable] [possible values: human-readable, json]\n      --exclude <EXCLUDES>...          Files to exclude from analysis\n  -V, --version                        Print version\n")

def parse_cli(argv):
    options={'no_lambda_arg':False,'no_lambda_pattern':False,'no_underscore':False,'warn_used_underscore':False,'quiet':False,'edit':False,'hidden':False,'fail':False,'output_format':'human-readable'}
    excludes=[];file_paths=[];i=1;n=len(argv)
    while i<n:
        arg=argv[i]
        if arg=='--':
            file_paths.extend(argv[i+1:]);break
        if arg=='--help':
            print_help();sys.exit(0)
        if arg in ('-V','--version'):
            print(VERSION);sys.exit(0)
        if arg in ('-l','--no-lambda-arg'):
            options['no_lambda_arg']=True;i+=1;continue
        if arg in ('-L','--no-lambda-pattern-names'):
            options['no_lambda_pattern']=True;i+=1;continue
        if arg in ('-_','--no-underscore'):
            options['no_underscore']=True;i+=1;continue
        if arg in ('-W','--warn-used-underscore'):
            options['warn_used_underscore']=True;i+=1;continue
        if arg in ('-q','--quiet'):
            options['quiet']=True;i+=1;continue
        if arg in ('-e','--edit'):
            options['edit']=True;i+=1;continue
        if arg in ('-h','--hidden'):
            options['hidden']=True;i+=1;continue
        if arg in ('-f','--fail'):
            options['fail']=True;i+=1;continue
        if arg.startswith('-o'):
            if arg=='-o':
                i+=1
                if i>=n:
                    print("error: missing value for -o",file=sys.stderr);sys.exit(2)
                val=argv[i]
                if val not in ('human-readable','json'):
                    print(f"error: invalid value '{val}' for '--output-format <OUTPUT_FORMAT>'\n  [possible values: human-readable, json]\n\nFor more information, try '--help'.",file=sys.stderr);sys.exit(2)
                options['output_format']=val;i+=1;continue
            elif arg.startswith('-o='):
                val=arg[3:]
                if val not in ('human-readable','json'):
                    print(f"error: invalid value '{val}' for '--output-format <OUTPUT_FORMAT>'\n  [possible values: human-readable, json]\n\nFor more information, try '--help'.",file=sys.stderr);sys.exit(2)
                options['output_format']=val;i+=1;continue
            elif len(arg)>2:
                val=arg[2:]
                if val.startswith('='):
                    val=val[1:]
                if val not in ('human-readable','json'):
                    print(f"error: invalid value '{val}' for '--output-format <OUTPUT_FORMAT>'\n  [possible values: human-readable, json]\n\nFor more information, try '--help'.",file=sys.stderr);sys.exit(2)
                options['output_format']=val;i+=1;continue
        if arg=='--output-format':
            i+=1
            if i>=n:
                print("error: missing value for --output-format",file=sys.stderr);sys.exit(2)
            val=argv[i]
            if val not in ('human-readable','json'):
                print(f"error: invalid value '{val}' for '--output-format <OUTPUT_FORMAT>'\n  [possible values: human-readable, json]\n\nFor more information, try '--help'.",file=sys.stderr);sys.exit(2)
            options['output_format']=val;i+=1;continue
        if arg.startswith('--output-format='):
            val=arg.split('=',1)[1]
            if val not in ('human-readable','json'):
                print(f"error: invalid value '{val}' for '--output-format <OUTPUT_FORMAT>'\n  [possible values: human-readable, json]\n\nFor more information, try '--help'.",file=sys.stderr);sys.exit(2)
            options['output_format']=val;i+=1;continue
        if arg=='--exclude':
            i+=1
            while i<n:
                nxt=argv[i]
                if nxt=='--':
                    break
                if nxt.startswith('-'):
                    known=['-l','--no-lambda-arg','-L','--no-lambda-pattern-names','-_','--no-underscore','-W','--warn-used-underscore','-q','--quiet','-e','--edit','-h','--hidden','--help','-f','--fail','-o','--output-format','--exclude','-V','--version']
                    is_opt=False
                    for ko in known:
                        if nxt==ko or nxt.startswith(ko+'='):
                            is_opt=True;break
                    if nxt.startswith('-o'):
                        is_opt=True
                    if nxt.startswith('--output-format'):
                        is_opt=True
                    if is_opt:
                        break
                    if nxt.startswith('-'):
                        break
                excludes.append(nxt);i+=1
            continue
        if arg.startswith('--exclude='):
            excludes.append(arg.split('=',1)[1]);i+=1;continue
        if arg.startswith('-') and not arg.startswith('--') and len(arg)>2:
            chars=arg[1:];j=0
            while j < len(chars):
                ch=chars[j]
                if ch=='l':
                    options['no_lambda_arg']=True
                elif ch=='L':
                    options['no_lambda_pattern']=True
                elif ch=='_':
                    options['no_underscore']=True
                elif ch=='W':
                    options['warn_used_underscore']=True
                elif ch=='q':
                    options['quiet']=True
                elif ch=='e':
                    options['edit']=True
                elif ch=='h':
                    options['hidden']=True
                elif ch=='f':
                    options['fail']=True
                elif ch=='V':
                    print(VERSION);sys.exit(0)
                elif ch=='o':
                    remaining=chars[j+1:]
                    if remaining:
                        val=remaining
                        if val.startswith('='):
                            val=val[1:]
                        if val not in ('human-readable','json'):
                            print(f"error: invalid value '{val}' for '--output-format <OUTPUT_FORMAT>'\n  [possible values: human-readable, json]\n\nFor more information, try '--help'.",file=sys.stderr);sys.exit(2)
                        options['output_format']=val
                        break
                    else:
                        i+=1
                        if i>=n:
                            print("error: missing value for -o",file=sys.stderr);sys.exit(2)
                        val=argv[i]
                        if val not in ('human-readable','json'):
                            print(f"error: invalid value '{val}' for '--output-format <OUTPUT_FORMAT>'\n  [possible values: human-readable, json]\n\nFor more information, try '--help'.",file=sys.stderr);sys.exit(2)
                        options['output_format']=val
                        break
                else:
                    print(f"error: unexpected argument '-{ch}' found\n\n  tip: to pass '-{ch}' as a value, use '-- -{ch}'\n\nUsage: executable [OPTIONS] [FILE_PATHS]...\n\nFor more information, try '--help'.",file=sys.stderr);sys.exit(2)
                j+=1
            i+=1;continue
        if arg.startswith('-'):
            print(f"error: unexpected argument '{arg}' found\n\n  tip: to pass '{arg}' as a value, use '-- {arg}'\n\nUsage: executable [OPTIONS] [FILE_PATHS]...\n\nFor more information, try '--help'.",file=sys.stderr);sys.exit(2)
        file_paths.append(arg);i+=1
    if not file_paths:
        file_paths=['.']
    return options,excludes,file_paths

def edit_file_simple(path,findings_detailed,options):
    source=pathlib.Path(path).read_text(encoding='utf-8')
    if not findings_detailed:
        return
    tokens,skip_lines,lines=lex(source)
    parser=Parser(tokens,source,lines,skip_lines)
    ast=parser.parse()
    let_nodes=[];lambda_nodes=[]
    def collect(node):
        if node is None:
            return
        t=node.get('type')
        if t=='let':
            let_nodes.append(node)
            for b in node['bindings']:
                if b['type']=='binding':
                    if b['expr']:
                        collect(b['expr'])
                elif b['type']=='inherit':
                    if b['from']:
                        collect(b['from'])
            collect(node['body'])
        elif t=='lambda':
            lambda_nodes.append(node)
            param=node['param']
            if param['type']=='pattern':
                for e in param['entries']:
                    if e['default']:
                        collect(e['default'])
            elif param['type']=='at_pattern':
                pat=param.get('pattern')
                if pat and pat['type']=='pattern':
                    for e in pat['entries']:
                        if e['default']:
                            collect(e['default'])
            collect(node['body'])
        elif t=='with':
            collect(node['expr']);collect(node['body'])
        elif t=='attrset':
            for b in node['bindings']:
                if b['type']=='attr_assign':
                    if b['expr']:
                        collect(b['expr'])
                elif b['type']=='inherit':
                    if b['from']:
                        collect(b['from'])
        elif t=='list':
            for e in node['elems']:
                collect(e)
        elif t=='app':
            collect(node['func'])
            for a in node['args']:
                collect(a)
        elif t=='string_interp':
            for e in node['exprs']:
                collect(e)
        elif t=='if':
            collect(node['cond']);collect(node['then']);collect(node['else'])
        elif t=='assert':
            collect(node['cond']);collect(node['body'])
    collect(ast)
    finding_keys=set((f['line'],f['col'],f['name']) for f in findings_detailed if f['type'] in ('let','let_used','lambda_pattern','lambda_pattern_used'))
    edits=[]
    for f in findings_detailed:
        if f['type']=='lambda_arg':
            tok=f['binding'].get('tok')
            if tok:
                edits.append((tok.offset,tok.end_offset,'_'+f['name'] if not f['name'].startswith('_') else f['name']))
    for let_node in let_nodes:
        unused=[]
        for b in let_node['bindings']:
            if b['type']=='binding':
                if (b['line'],b['col'],b['name']) in finding_keys:
                    unused.append(b)
            elif b['type']=='inherit':
                remaining=[ident for ident in b['idents'] if (ident['line'],ident['col'],ident['name']) not in finding_keys]
                if len(remaining)==0:
                    unused.append(b)
                elif len(remaining)<len(b['idents']):
                    start=b.get('start_offset',0)
                    semi=source.find(';',start)
                    if semi!=-1:
                        end=semi+1
                        orig=source[start:end]
                        from_text=""
                        if b['from'] is not None:
                            lpar=orig.find('(');rpar=orig.find(')',lpar)
                            if lpar!=-1 and rpar!=-1:
                                from_text=orig[lpar:rpar+1]
                        if from_text:
                            new=f"inherit {from_text} {' '.join([i['name'] for i in remaining])};"
                        else:
                            new=f"inherit {' '.join([i['name'] for i in remaining])};"
                        edits.append((start,end,new))
        if len(unused)==len(let_node['bindings']) and len(let_node['bindings'])>0:
            let_start=let_node.get('start_offset',0)
            m=re.search(r'\bin\b',source[let_start:])
            if m:
                in_end=let_start+m.end()
                body_start=in_end
                while body_start < len(source) and source[body_start] in ' \t\r\n':
                    body_start+=1
                edits=[e for e in edits if not (let_start <= e[0] < body_start and e[0]!=let_start)]
                edits.append((let_start,body_start,""))
        else:
            for b in unused:
                if b['type']=='binding':
                    tok=b.get('tok')
                    if not tok:
                        continue
                    start=tok.offset
                    semi=source.find(';',start)
                    if semi==-1:
                        continue
                    end=semi+1
                    j=end
                    while j < len(source) and source[j] in ' \t':
                        j+=1
                    line_start=source.rfind('\n',0,start)+1
                    prefix=source[line_start:start]
                    if prefix.strip()=='' or prefix.strip()=='let':
                        after=source[end:]
                        nl=after.find('\n')
                        if nl!=-1:
                            between=after[:nl]
                            if between.strip()=='':
                                end=end+nl+1
                                start=line_start
                            else:
                                end=j
                        else:
                            end=j
                    else:
                        end=j
                    edits.append((start,end,""))
                elif b['type']=='inherit':
                    start=b.get('start_offset',0)
                    semi=source.find(';',start)
                    if semi==-1:
                        continue
                    end=semi+1
                    line_start=source.rfind('\n',0,start)+1
                    prefix=source[line_start:start]
                    if prefix.strip()=='' or 'let' in prefix or 'inherit' in prefix:
                        after=source[end:]
                        nl=after.find('\n')
                        if nl!=-1 and after[:nl].strip()=='':
                            end=end+nl+1
                            start=line_start
                    edits.append((start,end,""))
    for lam in lambda_nodes:
        param=lam['param']
        if param['type']=='pattern':
            entries=param['entries']
            remaining=[e for e in entries if (e['line'],e['col'],e['name']) not in finding_keys]
            if len(remaining)==len(entries):
                continue
            l_off=param['l_brace'].offset if param.get('l_brace') else param.get('start_offset',0)
            r_off=source.find('}',l_off)
            if r_off==-1:
                continue
            inside_start=l_off+1;inside_end=r_off
            new_texts=[]
            for e in remaining:
                lt=lines[e['line']-1] if e['line']-1 < len(lines) else ""
                if e['default'] is not None:
                    mm=re.search(re.escape(e['name'])+r'\s*\?\s*([^,}\n]+)',lt)
                    if mm:
                        new_texts.append(f"{e['name']} ? {mm.group(1).strip()}")
                    else:
                        new_texts.append(e['name'])
                else:
                    new_texts.append(e['name'])
            if not new_texts:
                new_inside=" ... " if param['ellipsis'] else " "
            else:
                if param['ellipsis']:
                    new_inside=" " + ", ".join(new_texts) + ", ... "
                else:
                    new_inside=" " + ", ".join(new_texts) + " "
            edits.append((inside_start,inside_end,new_inside))
        elif param['type']=='at_pattern':
            at_name=param.get('at_name')
            pat=param.get('pattern')
            at_unused=False
            if at_name and (at_name['line'],at_name['col'],at_name['name']) in finding_keys:
                at_unused=True
            if pat and pat['type']=='pattern':
                entries=pat['entries']
                remaining=[e for e in entries if (e['line'],e['col'],e['name']) not in finding_keys]
                l_off=pat['l_brace'].offset if pat.get('l_brace') else pat.get('start_offset',0)
                r_off=source.find('}',l_off)
                if r_off==-1:
                    continue
                at_start=at_name['tok'].offset if at_name and at_name.get('tok') else l_off
                at_end=at_name['tok'].end_offset if at_name and at_name.get('tok') else l_off
                if at_start < l_off:
                    p_start=at_start; p_end=r_off+1
                else:
                    p_start=l_off; p_end=at_end
                if at_unused:
                    new_entries=[]
                    for e in remaining:
                        lt=lines[e['line']-1] if e['line']-1 < len(lines) else ""
                        if e['default'] is not None:
                            mm=re.search(re.escape(e['name'])+r'\s*\?\s*([^,}\n]+)',lt)
                            if mm:
                                new_entries.append(f"{e['name']} ? {mm.group(1).strip()}")
                            else:
                                new_entries.append(e['name'])
                        else:
                            new_entries.append(e['name'])
                    if not new_entries:
                        new_pat="{ ... }" if pat['ellipsis'] else "{ }"
                    else:
                        if pat['ellipsis']:
                            new_pat="{ " + ", ".join(new_entries) + ", ... }"
                        else:
                            new_pat="{ " + ", ".join(new_entries) + " }"
                    edits.append((p_start,p_end,new_pat))
                else:
                    if len(remaining)==len(entries):
                        continue
                    new_entries=[]
                    for e in remaining:
                        lt=lines[e['line']-1] if e['line']-1 < len(lines) else ""
                        if e['default'] is not None:
                            mm=re.search(re.escape(e['name'])+r'\s*\?\s*([^,}\n]+)',lt)
                            if mm:
                                new_entries.append(f"{e['name']} ? {mm.group(1).strip()}")
                            else:
                                new_entries.append(e['name'])
                        else:
                            new_entries.append(e['name'])
                    if not new_entries:
                        new_inside="{ ... }" if pat['ellipsis'] else "{ }"
                    else:
                        if pat['ellipsis']:
                            new_inside="{ " + ", ".join(new_entries) + ", ... }"
                        else:
                            new_inside="{ " + ", ".join(new_entries) + " }"
                    if at_start < l_off:
                        new_full=f"{at_name['name']}@{new_inside}"
                    else:
                        new_full=f"{new_inside}@{at_name['name']}"
                    edits.append((p_start,p_end,new_full))
    edits_sorted=sorted(edits,key=lambda x:x[0],reverse=True)
