            continue
        new_src=new_src[:s]+r+new_src[e:]
    pathlib.Path(path).write_text(new_src,encoding='utf-8')

def main():
    options,excludes,file_paths=parse_cli(sys.argv)
    files=find_nix_files(file_paths,hidden=options['hidden'],excludes=excludes)
    has=False
    json_out=[]
    human_files=[]
    for fp in files:
        if not os.path.exists(fp):
