                    print(f"Error stating file {fp}: No such file or directory (os error 2)")
            continue
        src,results,detailed,src_lines,tokens,ast,_=analyze_file(fp,options)
        if results:
            # check if results are only file-not-found? Already handled
            # For fail, any real unused counts
            # Determine if any result has message containing Unused or Used? For file not found, message does not contain Unused, but we still have has? Earlier we said file not found should not count for fail? But our earlier logic set has for file not found? Let's set has only if results contain Unused or Used
            for r in results:
                if 'Unused' in r.get('message','') or 'Used' in r.get('message',''):
                    has=True
                    break
            if options['output_format']=='json':
                json_out.append(json.dumps({"file":fp,"results":results}, separators=(',',':')))
            else:
                if not options['quiet']:
                    human_files.append((fp,src,detailed))
        if options['edit'] and src is not None and detailed:
            try:
                edit_file_simple(fp,detailed,options)
            except Exception as e:
                import traceback;traceback.print_exc()
    use_color=not os.environ.get('NO_COLOR')
